INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C1','math',3,1,'u2',2,'곧은 선과 굽은 선·변과 꼭짓점 — 곧은 선으로만 둘러싸인 도형을 가려내고, 도형을 이루는 곧은 선(변)과 두 변이 만나는 점(꼭짓점)을 세기',ARRAY['4수02-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C2','math',3,1,'u2',2,'선분·반직선·직선 — 두 점을 곧게 이은 선(선분), 한 점에서 한쪽으로 끝없이 늘인 선(반직선), 양쪽으로 끝없이 늘인 선(직선)을 구별하고 이름을 바르게 읽기(반직선은 시작점 먼저)',ARRAY['4수02-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C3','math',3,1,'u2',3,'각과 각의 꼭짓점·변 — 한 점에서 그은 두 반직선으로 이루어진 도형을 각이라 하고, 꼭짓점을 가운데에 두어 읽으며, 각의 크기는 변의 길이가 아니라 벌어진 정도로 견주기',ARRAY['4수02-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C4','math',3,1,'u2',4,'직각 — 종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라 하고, 삼각자의 직각 부분을 대어 확인하며 꼭짓점에 ㄱ자로 표시하기',ARRAY['4수02-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C5','math',3,1,'u2',5,'직각삼각형 — 한 각이 직각인 삼각형을 직각삼각형이라 하고, 놓인 방향이 달라도 직각이 있으면 직각삼각형임을 알기',ARRAY['4수02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C6','math',3,1,'u2',6,'직사각형 — 네 각이 모두 직각인 사각형을 직사각형이라 하고, 기울어져 놓여도 네 각을 모두 확인해 가려내기',ARRAY['4수02-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C7','math',3,1,'u2',6,'정사각형 — 네 각이 모두 직각이고 네 변의 길이가 모두 같은 사각형을 정사각형이라 하고, 정사각형은 직사각형이지만 직사각형이 모두 정사각형은 아님을 알기',ARRAY['4수02-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u2-C8','math',3,1,'u2',7,'평면도형으로 그림 그리기·도형 찾기 — 그림 속 평면도형의 이름과 수를 찾고, 크고 작은 도형을 빠짐없이 세며, 배운 도형으로 그림을 꾸미고 설명하기',ARRAY['4수02-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X01','math',3,'u2',ARRAY['M3-1-u2-C1','M3-1-u2-C2']::text[],'곧은 선과 굽은 선, 둘러싸인 것과 끊어진 것을 가리지 못한다 — 굽은 선이 섞이거나 열린 그림도 도형·선분이라고 한다','손가락으로 선을 따라가 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X02','math',3,'u2',ARRAY['M3-1-u2-C2','M3-1-u2-C8']::text[],'선분·반직선·직선을 끝의 모양으로 구별하지 못한다 — 끝이 있는 선과 끝없이 늘인 선을 섞는다','끝이 몇 개 있는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X03','math',3,'u2',ARRAY['M3-1-u2-C2']::text[],'반직선 ㄱㄴ과 반직선 ㄴㄱ을 같은 선이라고 생각한다 — 시작점을 먼저 읽는 약속을 놓친다','반직선은 시작점부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X05','math',3,'u2',ARRAY['M3-1-u2-C3','M3-1-u2-C4']::text[],'각을 읽을 때 꼭짓점을 가운데에 두지 않는다','꼭짓점은 가운데') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X06','math',3,'u2',ARRAY['M3-1-u2-C3','M3-1-u2-C4']::text[],'각의 꼭짓점과 변을 잘못 짚는다 — 변의 끝점을 꼭짓점이라 하거나 두 끝점을 이은 선을 변이라 한다','두 반직선이 만나는 점이 꼭짓점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X07','math',3,'u2',ARRAY['M3-1-u2-C3','M3-1-u2-C4']::text[],'변의 길이가 길수록 큰 각(큰 직각)이라고 생각한다','벌어진 정도를 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X08','math',3,'u2',ARRAY['M3-1-u2-C3','M3-1-u2-C4']::text[],'한 점에서 만나지 않는 두 선·굽은 선·곧은 선 하나도 각이라고 한다','한 점에서 그은 두 반직선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X09','math',3,'u2',ARRAY['M3-1-u2-C4','M3-1-u2-C5','M3-1-u2-C6','M3-1-u2-C8']::text[],'직각을 눈대중으로 판단한다 — 직각에 가까운 각을 직각이라 하거나 직각을 빠뜨린다','삼각자를 대어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X10','math',3,'u2',ARRAY['M3-1-u2-C4','M3-1-u2-C5','M3-1-u2-C6','M3-1-u2-C7']::text[],'도형이 기울어져 놓이면 직각·직각삼각형·직사각형이 아니라고 생각한다','돌려 놓아도 같은 도형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X11','math',3,'u2',ARRAY['M3-1-u2-C5']::text[],'직각삼각형의 직각이 둘 이상일 수 있다고 생각하거나 직각삼각형의 조건을 잘못 안다','직각은 한 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X12','math',3,'u2',ARRAY['M3-1-u2-C6','M3-1-u2-C7','M3-1-u2-C8']::text[],'사각형을 가를 때 네 각을 모두 확인하지 않는다 — 직각이 한두 개만 있거나 네 변만 같아도 직사각형·정사각형이라고 한다','네 각을 모두 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X13','math',3,'u2',ARRAY['M3-1-u2-C6','M3-1-u2-C7']::text[],'정사각형은 직사각형이 아니라고 생각한다','정사각형도 네 각이 직각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X14','math',3,'u2',ARRAY['M3-1-u2-C6','M3-1-u2-C7']::text[],'직사각형은 네 변의 길이가 모두 같아야 한다(직사각형은 모두 정사각형)고 생각한다','직사각형은 각만, 정사각형은 각과 변') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X15','math',3,'u2',ARRAY['M3-1-u2-C1','M3-1-u2-C2','M3-1-u2-C3','M3-1-u2-C4','M3-1-u2-C5','M3-1-u2-C6','M3-1-u2-C7','M3-1-u2-C8']::text[],'도형·선·각을 셀 때 겹친 큰 도형을 빠뜨리거나 같은 것을 두 번 센다','작은 것부터 큰 것까지 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u2-X16','math',3,'u2',ARRAY['M3-1-u2-C1','M3-1-u2-C2','M3-1-u2-C3','M3-1-u2-C4','M3-1-u2-C5','M3-1-u2-C6','M3-1-u2-C7','M3-1-u2-C8']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
