INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#4','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',3,'error','auto','이 반직선을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u2-X03','M3-1-u2-X16']::text[],true,'{"seq":4,"concept":"M3-1-u2-C2","difficulty":3,"kind":"error","stem":"이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㄱㄴ은 반직선 ㄴㄱ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㄱㄴ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㄱ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㄴ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㄱ에서 시작하니 반직선 ㄱㄴ이에요.","반직선 ㄴㄱ은 점 ㄴ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄱ":[45,45],"ㄴ":[97.5,45]},"ray":[["ㄱ","ㄴ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㄷㄹ은 반직선 ㄹㄷ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㄷㄹ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㄷ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㄹ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㄷ에서 시작하니 반직선 ㄷㄹ이에요.","반직선 ㄹㄷ은 점 ㄹ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄷ":[45,60],"ㄹ":[97.5,30]},"ray":[["ㄷ","ㄹ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㅁㅂ은 반직선 ㅂㅁ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㅁㅂ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㅁ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅂ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㅁ에서 시작하니 반직선 ㅁㅂ이에요.","반직선 ㅂㅁ은 점 ㅂ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅁ":[45,30],"ㅂ":[97.5,60]},"ray":[["ㅁ","ㅂ"]]}],"tag":false}}]}}'