INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#5','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',3,'mc','auto','그림에서 선분은 모두 몇 개인가요?',ARRAY['M3-1-u2-X02','M3-1-u2-X15']::text[],true,'{"seq":5,"concept":"M3-1-u2-C2","difficulty":3,"kind":"mc","stem":"그림에서 선분은 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M3-1-u2-X02"},{"t":"1개","mis":"M3-1-u2-X15"},{"t":"4개","mis":"M3-1-u2-X15"}],"explanation":["두 끝이 모두 점에서 멈춘 곧은 선만 선분이에요.","한쪽이나 양쪽으로 그림 끝까지 뻗은 선은 반직선·직선이에요.","선분은 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"pts":{"ㄱ":[15,15],"ㄴ":[60,15],"ㄷ":[90,45],"ㄹ":[15,75],"ㅁ":[75,75]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]],"ray":[["ㄹ","ㅁ"]],"line":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 선분은 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M3-1-u2-X15"},{"t":"4개","mis":"M3-1-u2-X15"},{"t":"5개","mis":"M3-1-u2-X15"}],"explanation":["두 끝이 모두 점에서 멈춘 곧은 선만 선분이에요.","한쪽이나 양쪽으로 그림 끝까지 뻗은 선은 반직선·직선이에요 — 이 그림에는 없어요.","선분은 3개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"pts":{"ㄱ":[15,22.5],"ㄴ":[75,15],"ㄷ":[30,60],"ㄹ":[90,67.5],"ㅁ":[45,45],"ㅂ":[105,37.5]},"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㅁ","ㅂ"]],"ray":[],"line":[]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 선분은 모두 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M3-1-u2-X02"},{"t":"1개","mis":"M3-1-u2-X15"},{"t":"4개","mis":"M3-1-u2-X15"}],"explanation":["두 끝이 모두 점에서 멈춘 곧은 선만 선분이에요.","한쪽이나 양쪽으로 그림 끝까지 뻗은 선은 반직선·직선이에요.","선분은 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"pts":{"ㄱ":[15,15],"ㄴ":[75,22.5],"ㄷ":[22.5,52.5],"ㄹ":[90,45],"ㅁ":[30,82.5],"ㅂ":[105,75]},"seg":[["ㄱ","ㄴ"],["ㅁ","ㅂ"]],"ray":[["ㄷ","ㄹ"]],"line":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#6','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',3,'ox','auto','직선 ㅅㅇ의 길이는 자로 잴 수 있어요.',ARRAY['M3-1-u2-X02']::text[],true,'{"seq":6,"concept":"M3-1-u2-C2","difficulty":3,"kind":"ox","stem":"직선 ㅅㅇ의 길이는 자로 잴 수 있어요.","answer":"X","reason_options":[{"t":"직선은 끝없이 늘어나 끝이 정해지지 않아서","correct":true},{"t":"두 점 사이만 재면 되어서","mis":"M3-1-u2-X02"}],"mis":"M3-1-u2-X02","explanation":["선분은 두 끝이 있어 길이를 잴 수 있어요.","직선은 양쪽으로 끝없이 늘어나요.","그래서 직선은 끝이 정해지지 않아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅅ":[45,60],"ㅇ":[97.5,30]},"line":[["ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"반직선 ㄴㄷ의 길이는 자로 잴 수 있어요.","answer":"X","reason_options":[{"t":"반직선은 끝없이 늘어나 끝이 정해지지 않아서","correct":true},{"t":"두 점 사이만 재면 되어서","mis":"M3-1-u2-X02"}],"explanation":["선분은 두 끝이 있어 길이를 잴 수 있어요.","반직선은 한쪽으로 끝없이 늘어나요.","그래서 반직선은 끝이 정해지지 않아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄴ":[45,30],"ㄷ":[97.5,60]},"ray":[["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"직선 ㄹㅁ은 점 ㄹ과 점 ㅁ에서 끝나요.","answer":"X","reason_options":[{"t":"직선은 끝없이 늘어나 끝이 정해지지 않아서","correct":true},{"t":"두 점 사이만 재면 되어서","mis":"M3-1-u2-X02"}],"explanation":["선분은 두 끝이 있어 길이를 잴 수 있어요.","직선은 양쪽으로 끝없이 늘어나요.","그래서 직선은 끝이 정해지지 않아요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄹ":[45,54.0],"ㅁ":[97.5,36.0]},"line":[["ㄹ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#7','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C1',3,'sa','auto','곰이가 등굣길 지도에 삼각형 1개와 사각형 2개를 그렸어요. 곰이가 그린 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u2-C1","difficulty":3,"kind":"sa","stem":"곰이가 등굣길 지도에 삼각형 1개와 사각형 2개를 그렸어요. 곰이가 그린 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["삼각형 하나에 꼭짓점 3개, 사각형 하나에 꼭짓점 4개예요.","삼각형: 3 = 3, 사각형: 4 + 4 = 8.","3 + 8 = 11개예요."],"variant_rule":{"alt":[{"stem":"곰이가 등굣길 지도에 삼각형 2개와 사각형 1개를 그렸어요. 곰이가 그린 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["삼각형 하나에 꼭짓점 3개, 사각형 하나에 꼭짓점 4개예요.","삼각형: 3 + 3 = 6, 사각형: 4 = 4.","6 + 4 = 10개예요."],"asset":null},{"stem":"곰이가 등굣길 지도에 삼각형 3개와 사각형 2개를 그렸어요. 곰이가 그린 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["삼각형 하나에 꼭짓점 3개, 사각형 하나에 꼭짓점 4개예요.","삼각형: 3 + 3 + 3 = 9, 사각형: 4 + 4 = 8.","9 + 8 = 17개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#8','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',4,'mc','auto','세 점 ㄱ, ㄴ, ㄷ이 한 직선 위에 차례로 있어요. 반직선 ㄱㄴ과 반직선 ㄱㄷ은 같은 반직선인가요?',ARRAY['M3-1-u2-X03','M3-1-u2-X02','M3-1-u2-X16']::text[],true,'{"seq":8,"concept":"M3-1-u2-C2","difficulty":4,"kind":"mc","stem":"세 점 ㄱ, ㄴ, ㄷ이 한 직선 위에 차례로 있어요. 반직선 ㄱㄴ과 반직선 ㄱㄷ은 같은 반직선인가요?","options":[{"t":"같아요 — 시작점 ㄱ이 같고 같은 쪽으로 늘어나서","correct":true},{"t":"달라요 — 지나는 점이 ㄴ과 ㄷ으로 달라서","mis":"M3-1-u2-X03"},{"t":"달라요 — 반직선 ㄱㄷ이 더 길어서","mis":"M3-1-u2-X02"},{"t":"알 수 없어요","mis":"M3-1-u2-X16"}],"explanation":["두 반직선 모두 점 ㄱ에서 시작해요.","둘 다 ㄴ·ㄷ 쪽으로 끝없이 늘어나 겹쳐요.","그래서 같은 반직선이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄱ":[22.5,45],"ㄴ":[67.5,45],"ㄷ":[112.5,45]},"line":[["ㄱ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"세 점 ㄱ, ㄴ, ㄷ이 한 직선 위에 차례로 있어요. 반직선 ㄴㄱ과 반직선 ㄴㄷ은 같은 반직선인가요?","options":[{"t":"달라요 — 시작점은 같지만 늘어나는 쪽이 반대라서","correct":true},{"t":"같아요 — 시작점 ㄴ이 같아서","mis":"M3-1-u2-X03"},{"t":"같아요 — 모두 한 직선 위에 있어서","mis":"M3-1-u2-X02"},{"t":"알 수 없어요","mis":"M3-1-u2-X16"}],"explanation":["두 반직선 모두 점 ㄴ에서 시작해요.","반직선 ㄴㄱ은 ㄱ 쪽, 반직선 ㄴㄷ은 ㄷ 쪽으로 늘어나요.","늘어나는 쪽이 반대라 서로 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄱ":[22.5,45],"ㄴ":[67.5,45],"ㄷ":[112.5,45]},"line":[["ㄱ","ㄷ"]]}],"tag":false}},{"stem":"세 점 ㄹ, ㅁ, ㅂ이 한 직선 위에 차례로 있어요. 반직선 ㄹㅁ과 반직선 ㄹㅂ은 같은 반직선인가요?","options":[{"t":"같아요 — 시작점 ㄹ이 같고 같은 쪽으로 늘어나서","correct":true},{"t":"달라요 — 지나는 점이 ㅁ과 ㅂ으로 달라서","mis":"M3-1-u2-X03"},{"t":"달라요 — 반직선 ㄹㅂ이 더 길어서","mis":"M3-1-u2-X02"},{"t":"알 수 없어요","mis":"M3-1-u2-X16"}],"explanation":["두 반직선 모두 점 ㄹ에서 시작해요.","둘 다 ㅁ·ㅂ 쪽으로 끝없이 늘어나 겹쳐요.","그래서 같은 반직선이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄹ":[22.5,45],"ㅁ":[67.5,45],"ㅂ":[112.5,45]},"line":[["ㄹ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#9','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',4,'essay','teacher','선분, 반직선, 직선의 같은 점과 다른 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C2","difficulty":4,"kind":"essay","stem":"선분, 반직선, 직선의 같은 점과 다른 점을 써 보세요.","answer_guide":{"answer":"예: 같은 점 — 셋 다 곧은 선이다. 다른 점 — 선분은 두 점을 곧게 이어 끝이 2개, 반직선은 한 점에서 시작해 한쪽으로 끝없이 늘어나 끝이 1개, 직선은 양쪽으로 끝없이 늘어나 끝이 없다.","scoring_points":["셋 다 곧은 선이라고 썼는가","끝의 수(2개·1개·없음)나 늘어나는 쪽으로 다른 점을 썼는가","반직선은 시작점이 있다는 것을 드러냈는가"]},"explanation":["같은 점: 모두 곧은 선이에요.","다른 점: 선분 끝 2개 · 반직선 끝 1개 · 직선 끝 없음.","반직선은 시작하는 점을 먼저 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L02_challenge#10','math',3,1,'u2','L02','g3_1_math_u2_L02_challenge','lesson_challenge','M3-1-u2-C2',4,'sa','auto','한 직선 위에 점 3개(ㄱ, ㄴ, ㄷ)가 차례로 있어요. 이 점들 가운데 두 점을 이어 만들 수 있는 선분은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u2-C2","difficulty":4,"kind":"sa","stem":"한 직선 위에 점 3개(ㄱ, ㄴ, ㄷ)가 차례로 있어요. 이 점들 가운데 두 점을 이어 만들 수 있는 선분은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["짧은 선분부터 세어요 — 이웃한 두 점: 2개.","사이에 점이 끼어 있는 긴 선분도 선분이에요 — 빠뜨리지 않아요.","모두 2 + 1 = 3개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄱ":[15.0,45],"ㄴ":[67.5,45],"ㄷ":[120.0,45]},"seg":[["ㄱ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 직선 위에 점 4개(ㄹ, ㅁ, ㅂ, ㅅ)가 차례로 있어요. 이 점들 가운데 두 점을 이어 만들 수 있는 선분은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["짧은 선분부터 세어요 — 이웃한 두 점: 3개.","사이에 점이 끼어 있는 긴 선분도 선분이에요 — 빠뜨리지 않아요.","모두 3 + 2 + 1 = 6개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄹ":[15.0,45],"ㅁ":[50.0,45],"ㅂ":[85.0,45],"ㅅ":[120.0,45]},"seg":[["ㄹ","ㅅ"]]}],"tag":false}},{"stem":"한 직선 위에 점 5개(ㅁ, ㅂ, ㅅ, ㅇ, ㅈ)가 차례로 있어요. 이 점들 가운데 두 점을 이어 만들 수 있는 선분은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["짧은 선분부터 세어요 — 이웃한 두 점: 4개.","사이에 점이 끼어 있는 긴 선분도 선분이에요 — 빠뜨리지 않아요.","모두 4 + 3 + 2 + 1 = 10개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㅁ":[15.0,45],"ㅂ":[41.25,45],"ㅅ":[67.5,45],"ㅇ":[93.75,45],"ㅈ":[120.0,45]},"seg":[["ㅁ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L03_basic#1','math',3,1,'u2','L03','g3_1_math_u2_L03_basic','lesson_basic','M3-1-u2-C3',1,'mc','auto','각 ㄱㄴㄷ의 꼭짓점은 어느 것인가요?',ARRAY['M3-1-u2-X06']::text[],true,'{"seq":1,"concept":"M3-1-u2-C3","difficulty":1,"kind":"mc","stem":"각 ㄱㄴㄷ의 꼭짓점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄱ","mis":"M3-1-u2-X06"},{"t":"점 ㄷ","mis":"M3-1-u2-X06"},{"t":"변 ㄱㄷ","mis":"M3-1-u2-X06"}],"explanation":["각을 읽을 때는 꼭짓점을 가운데에 써요.","각 ㄱㄴㄷ의 가운데 글자는 ㄴ — 꼭짓점은 점 ㄴ이에요.","점 ㄱ과 점 ㄷ은 두 변 위에 있는 점이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄱ":[120.0,75.0],"ㄴ":[22.5,75],"ㄷ":[67.5,7.5]},"ray":[["ㄴ","ㄱ"],["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"각 ㄹㅁㅂ의 꼭짓점은 어느 것인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M3-1-u2-X06"},{"t":"점 ㅂ","mis":"M3-1-u2-X06"},{"t":"변 ㄹㅂ","mis":"M3-1-u2-X06"}],"explanation":["각을 읽을 때는 꼭짓점을 가운데에 써요.","각 ㄹㅁㅂ의 가운데 글자는 ㅁ — 꼭짓점은 점 ㅁ이에요.","점 ㄹ과 점 ㅂ은 두 변 위에 있는 점이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄹ":[120.0,75.0],"ㅁ":[15,75],"ㅂ":[90.0,22.5]},"ray":[["ㅁ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false}},{"stem":"각 ㅅㅇㅈ의 꼭짓점은 어느 것인가요?","options":[{"t":"점 ㅇ","correct":true},{"t":"점 ㅅ","mis":"M3-1-u2-X06"},{"t":"점 ㅈ","mis":"M3-1-u2-X06"},{"t":"변 ㅅㅈ","mis":"M3-1-u2-X06"}],"explanation":["각을 읽을 때는 꼭짓점을 가운데에 써요.","각 ㅅㅇㅈ의 가운데 글자는 ㅇ — 꼭짓점은 점 ㅇ이에요.","점 ㅅ과 점 ㅈ은 두 변 위에 있는 점이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅅ":[127.5,75.0],"ㅇ":[67.5,75],"ㅈ":[15.0,15.0]},"ray":[["ㅇ","ㅅ"],["ㅇ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_a