INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L03_basic#2','math',3,1,'u2','L03','g3_1_math_u2_L03_basic','lesson_basic','M3-1-u2-C3',1,'mc','auto','그림의 각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u2-X05']::text[],true,'{"seq":2,"concept":"M3-1-u2-C3","difficulty":1,"kind":"mc","stem":"그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㄹㅁㅂ","correct":true},{"t":"각 ㄹㅂㅁ","mis":"M3-1-u2-X05"},{"t":"각 ㅁㄹㅂ","mis":"M3-1-u2-X05"},{"t":"각 ㅁㅂㄹ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㅁ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㄹㅁㅂ 또는 각 ㅂㅁㄹ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄹ":[120.0,60.0],"ㅁ":[30,75],"ㅂ":[60.0,7.5]},"ray":[["ㅁ","ㄹ"],["ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㅅㅇㅈ","correct":true},{"t":"각 ㅅㅈㅇ","mis":"M3-1-u2-X05"},{"t":"각 ㅇㅅㅈ","mis":"M3-1-u2-X05"},{"t":"각 ㅇㅈㅅ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㅇ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㅅㅇㅈ 또는 각 ㅈㅇㅅ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅅ":[127.5,67.5],"ㅇ":[75,67.5],"ㅈ":[7.5,22.5]},"ray":[["ㅇ","ㅅ"],["ㅇ","ㅈ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㄷㄹㅁ","correct":true},{"t":"각 ㄷㅁㄹ","mis":"M3-1-u2-X05"},{"t":"각 ㄹㄷㅁ","mis":"M3-1-u2-X05"},{"t":"각 ㄹㅁㄷ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㄹ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㄷㄹㅁ 또는 각 ㅁㄹㄷ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄷ":[120.0,75.0],"ㄹ":[30,75],"ㅁ":[30.0,7.5]},"ray":[["ㄹ","ㄷ"],["ㄹ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXC