INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L03_basic#10','math',3,1,'u2','L03','g3_1_math_u2_L03_basic','lesson_basic','M3-1-u2-C3',3,'mc','auto','각에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M3-1-u2-X07','M3-1-u2-X08','M3-1-u2-X06']::text[],true,'{"seq":10,"concept":"M3-1-u2-C3","difficulty":3,"kind":"mc","stem":"각에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"한 점에서 그은 두 반직선으로 이루어진 도형이에요","correct":true},{"t":"변의 길이가 길수록 큰 각이에요","mis":"M3-1-u2-X07"},{"t":"곧은 선 하나로 이루어진 도형이에요","mis":"M3-1-u2-X08"},{"t":"꼭짓점은 두 변의 끝에 하나씩 있어요","mis":"M3-1-u2-X06"}],"explanation":["각은 한 점에서 그은 두 반직선으로 이루어져요.","꼭짓점은 두 반직선이 만나는 점 — 읽을 때 가운데에 써요.","각의 크기는 벌어진 정도로 정해져요(변의 길이와 상관없어요)."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 각에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"각의 크기는 두 변이 벌어진 정도로 정해져요","correct":true},{"t":"각의 크기는 변의 길이로 정해져요","mis":"M3-1-u2-X07"},{"t":"두 선이 만나지 않아도 각이에요","mis":"M3-1-u2-X08"},{"t":"각을 읽을 때 꼭짓점은 맨 앞에 써요","mis":"M3-1-u2-X05"}],"explanation":["각은 한 점에서 그은 두 반직선으로 이루어져요.","꼭짓점은 두 반직선이 만나는 점 — 읽을 때 가운데에 써요.","각의 크기는 벌어진 정도로 정해져요(변의 길이와 상관없어요)."],"asset":null},{"stem":"이번에는 다른 그림이에요. 각에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"각을 읽을 때는 꼭짓점을 가운데에 써요","correct":true},{"t":"각을 읽을 때는 꼭짓점을 맨 끝에 써요","mis":"M3-1-u2-X05"},{"t":"굽은 선 두 개로도 각을 만들 수 있어요","mis":"M3-1-u2-X08"},{"t":"변을 길게 늘이면 각이 커져요","mis":"M3-1-u2-X07"}],"explanation":["각은 한 점에서 그은 두 반직선으로 이루어져요.","꼭짓점은 두 반직선이 만나는 점 — 읽을 때 가운데에 써요.","각의 크기는 벌어진 정도로 정해져요(변의 길이와 상관없어요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
