INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L03_challenge#8','math',3,1,'u2','L03','g3_1_math_u2_L03_challenge','lesson_challenge','M3-1-u2-C3',4,'sa','auto','사각형 ㄱㄴㄷㄹ에 선분 ㄱㄷ을 그었어요. 점 ㄱ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u2-C3","difficulty":4,"kind":"sa","stem":"사각형 ㄱㄴㄷㄹ에 선분 ㄱㄷ을 그었어요. 점 ㄱ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄱ에서 변 ㄱㄴ, 선분 ㄱㄷ, 변 ㄱㄹ 세 선이 나가요.","작은 각 각 ㄴㄱㄷ, 각 ㄷㄱㄹ — 2개.","두 각을 합친 큰 각 ㄴㄱㄹ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[105,15],"ㄷ":[105,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㅁㅂㅅㅇ에 선분 ㅁㅅ을 그었어요. 점 ㅁ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㅁ에서 변 ㅁㅂ, 선분 ㅁㅅ, 변 ㅁㅇ 세 선이 나가요.","작은 각 각 ㅂㅁㅅ, 각 ㅅㅁㅇ — 2개.","두 각을 합친 큰 각 ㅂㅁㅇ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㅁ":[30,15],"ㅂ":[90,15],"ㅅ":[90,75],"ㅇ":[30,75]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[["ㅁ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 사각형 ㄱㄴㄷㄹ에 선분 ㄱㄷ을 그었어요. 점 ㄱ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄱ에서 변 ㄱㄴ, 선분 ㄱㄷ, 변 ㄱㄹ 세 선이 나가요.","작은 각 각 ㄴㄱㄷ, 각 ㄷㄱㄹ — 2개.","두 각을 합친 큰 각 ㄴㄱㄹ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㄱ":[30,15],"ㄴ":[105,15],"ㄷ":[90,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L03_challenge#9','math',3,1,'u2','L03','g3_1_math_u2_L03_challenge','lesson_challenge','M3-1-u2-C3',4,'essay','teacher','지유는 「두 각 가운데 변이 더 긴 각이 더 큰 각이야.」라고 말했어요. 지유의 말이 잘못된 까닭과 두 각의 크기를 견주는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C3","difficulty":4,"kind":"essay","stem":"지유는 「두 각 가운데 변이 더 긴 각이 더 큰 각이야.」라고 말했어요. 지유의 말이 잘못된 까닭과 두 각의 크기를 견주는 방법을 써 보세요.","answer_guide":{"answer":"예: 각의 변은 반직선이라 끝없이 늘어나므로 변의 길이로 각의 크기를 정할 수 없다. 두 각의 꼭짓점과 한 변을 맞대어 겹쳐 보고 두 변이 더 많이 벌어진 쪽이 더 큰 각이다.","scoring_points":["변의 길이와 각의 크기는 상관없다고 썼는가","벌어진 정도로 견준다고 썼는가","꼭짓점·한 변을 맞대어 겹쳐 보는 등 견주는 방법을 썼는가"]},"explanation":["각의 변은 반직선이라 길이로 정할 수 없어요.","각의 크기 = 두 변이 벌어진 정도.","꼭짓점과 한 변을 맞대어 겹쳐 보면 견줄 수 있어요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"pts":{"ㄱ":[120.0,75.0],"ㄴ":[15,75],"ㄷ":[90.0,22.5]},"seg":[["ㄴ","ㄱ"],["ㄴ","ㄷ"]]},{"w":135,"h":90,"pts":{"ㄹ":[70.5,68.25],"ㅁ":[30,75],"ㅂ":[43.5,44.625]},"seg":[["ㅁ","ㄹ"],["ㅁ","ㅂ"]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
