INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_basic#1','math',3,1,'u2','L04','g3_1_math_u2_L04_basic','lesson_basic','M3-1-u2-C4',1,'mc','auto','종이를 반듯하게 두 번 접었다가 펼쳤을 때 접힌 선이 만나 생기는 각을 무엇이라고 하나요?',ARRAY['M3-1-u2-X08','M3-1-u2-X06']::text[],true,'{"seq":1,"concept":"M3-1-u2-C4","difficulty":1,"kind":"mc","stem":"종이를 반듯하게 두 번 접었다가 펼쳤을 때 접힌 선이 만나 생기는 각을 무엇이라고 하나요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"꼭짓점","mis":"M3-1-u2-X06"},{"t":"곧은 선","mis":"M3-1-u2-X08"}],"explanation":["종이를 반듯하게 두 번 접으면 생기는 각이 직각이에요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"variant_rule":{"alt":[{"stem":"직각을 나타낼 때 꼭짓점에 하는 표시는 무엇인가요?","options":[{"t":"ㄱ자 표시","correct":true},{"t":"동그라미 표시","mis":"M3-1-u2-X09"},{"t":"꼭짓점에 점 찍기","mis":"M3-1-u2-X06"},{"t":"변에 화살표","mis":"M3-1-u2-X02"}],"explanation":["직각은 꼭짓점에 작은 ㄱ자로 표시해요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"asset":null},{"stem":"각이 직각인지 알아볼 때 대어 보는 도구는 무엇인가요?","options":[{"t":"삼각자","correct":true},{"t":"지우개","mis":"M3-1-u2-X09"},{"t":"풀","mis":"M3-1-u2-X09"},{"t":"연필","mis":"M3-1-u2-X09"}],"explanation":["삼각자의 직각 부분을 대어 꼭 맞으면 직각이에요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
