INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_basic#10','math',3,1,'u2','L04','g3_1_math_u2_L04_basic','lesson_basic','M3-1-u2-C4',3,'sa','auto','두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u2-C4","difficulty":3,"kind":"sa","stem":"두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","두 직선이 직각으로 만나는 점 둘레에 직각이 4개 생겨요.","직각은 모두 4개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"seg":[[[15,45],[120,45]],[[67.5,7.5],[67.5,82.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","곧은 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,67.5],[120,67.5]],[[67.5,67.5],[67.5,7.5]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","기울어진 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[90,52.5]],[[52.5,33.75],[37.5,63.75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#1','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',2,'mc','auto','긴바늘이 12를 가리키는 시각 가운데 두 바늘이 직각을 이루는 시각을 모두 고른 것은 어느 것인가요?',ARRAY['M3-1-u2-X08','M3-1-u2-X09']::text[],true,'{"seq":1,"concept":"M3-1-u2-C4","difficulty":2,"kind":"mc","stem":"긴바늘이 12를 가리키는 시각 가운데 두 바늘이 직각을 이루는 시각을 모두 고른 것은 어느 것인가요?","options":[{"t":"3시와 9시","correct":true},{"t":"3시와 6시","mis":"M3-1-u2-X08"},{"t":"6시와 12시","mis":"M3-1-u2-X08"},{"t":"2시와 10시","mis":"M3-1-u2-X09"}],"explanation":["짧은바늘이 3이나 9를 가리키면 12를 가리키는 긴바늘과 반듯하게 꺾여요.","6시는 두 바늘이 곧은 선, 12시는 겹쳐요.","그래서 3시와 9시 두 시각이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 긴바늘이 12를 가리키는 시각 가운데 두 바늘이 직각을 이루는 시각을 모두 고른 것은 어느 것인가요?","options":[{"t":"9시와 3시","correct":true},{"t":"9시와 6시","mis":"M3-1-u2-X08"},{"t":"12시와 6시","mis":"M3-1-u2-X08"},{"t":"4시와 8시","mis":"M3-1-u2-X09"}],"explanation":["짧은바늘이 3이나 9를 가리키면 12를 가리키는 긴바늘과 반듯하게 꺾여요.","6시는 두 바늘이 곧은 선, 12시는 겹쳐요.","그래서 3시와 9시 두 시각이에요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 긴바늘이 12를 가리키는 시각 가운데 두 바늘이 직각을 이루는 시각을 모두 고른 것은 어느 것인가요?","options":[{"t":"3시와 9시","correct":true},{"t":"3시 하나뿐이에요","mis":"M3-1-u2-X15"},{"t":"1시와 11시","mis":"M3-1-u2-X09"},{"t":"6시 하나뿐이에요","mis":"M3-1-u2-X08"}],"explanation":["짧은바늘이 3이나 9를 가리키면 12를 가리키는 긴바늘과 반듯하게 꺾여요.","6시는 두 바늘이 곧은 선, 12시는 겹쳐요.","그래서 3시와 9시 두 시각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#2','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',2,'sa','auto','모눈 위에 그린 도형에서 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u2-C4","difficulty":2,"kind":"sa","stem":"모눈 위에 그린 도형에서 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["꼭짓점마다 삼각자의 직각 부분을 대어 봐요.","직각인 꼭짓점은 1군데예요.","그래서 직각은 1개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[90,15],[90,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 도형에서 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["꼭짓점마다 삼각자의 직각 부분을 대어 봐요.","직각인 꼭짓점은 4군데예요.","그래서 직각은 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[75,30],[60,75],[15,60]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위에 그린 도형에서 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["꼭짓점마다 삼각자의 직각 부분을 대어 봐요.","꼭 맞는 꼭짓점이 없어요.","그래서 직각은 0개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[105,15],[90,75],[15,75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
