INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#4','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',3,'sa','auto','두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u2-C4","difficulty":3,"kind":"sa","stem":"두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","곧은 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,67.5],[120,67.5]],[[67.5,67.5],[67.5,7.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","기울어진 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[90,52.5]],[[52.5,33.75],[37.5,63.75]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","두 직선이 직각으로 만나는 점 둘레에 직각이 4개 생겨요.","직각은 모두 4개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"seg":[[[15,45],[120,45]],[[67.5,7.5],[67.5,82.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#5','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',3,'ox','auto','삼각자의 직각 부분을 대었을 때 틈이 조금 생기면 직각이 아니에요.',ARRAY['M3-1-u2-X09']::text[],true,'{"seq":5,"concept":"M3-1-u2-C4","difficulty":3,"kind":"ox","stem":"삼각자의 직각 부분을 대었을 때 틈이 조금 생기면 직각이 아니에요.","answer":"O","reason_options":[{"t":"직각은 삼각자에 꼭 맞아야 하는 각이라서","correct":true},{"t":"비슷하게 반듯해 보이면 직각이라고 해도 되어서","mis":"M3-1-u2-X09"}],"mis":"M3-1-u2-X09","explanation":["직각은 크기가 정해진 각이에요.","삼각자의 직각이나 두 번 접은 종이에 대어 꼭 맞아야 해요.","틈이 생기거나 넘치면 직각이 아니에요."],"variant_rule":{"alt":[{"stem":"눈으로 보아 반듯해 보여도 삼각자를 대어 보아야 직각인지 알 수 있어요.","answer":"O","reason_options":[{"t":"직각은 삼각자에 꼭 맞아야 하는 각이라서","correct":true},{"t":"비슷하게 반듯해 보이면 직각이라고 해도 되어서","mis":"M3-1-u2-X09"}],"explanation":["직각은 크기가 정해진 각이에요.","삼각자의 직각이나 두 번 접은 종이에 대어 꼭 맞아야 해요.","틈이 생기거나 넘치면 직각이 아니에요."],"asset":null},{"stem":"종이를 반듯하게 두 번 접은 각에 대어 꼭 맞으면 직각이에요.","answer":"O","reason_options":[{"t":"직각은 삼각자에 꼭 맞아야 하는 각이라서","correct":true},{"t":"비슷하게 반듯해 보이면 직각이라고 해도 되어서","mis":"M3-1-u2-X09"}],"explanation":["직각은 크기가 정해진 각이에요.","삼각자의 직각이나 두 번 접은 종이에 대어 꼭 맞아야 해요.","틈이 생기거나 넘치면 직각이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#6','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',3,'error','auto','각이 직각인지 알아본 방법이 잘못된 친구는 누구인가요?',ARRAY['M3-1-u2-X09','M3-1-u2-X16']::text[],true,'{"seq":6,"concept":"M3-1-u2-C4","difficulty":3,"kind":"error","stem":"각이 직각인지 알아본 방법이 잘못된 친구는 누구인가요?","options":[{"t":"은우 — 「눈으로 보니 반듯해 보여서 직각이라고 했어.」","correct":true,"mis_target":"M3-1-u2-X09"},{"t":"서윤 — 「삼각자의 직각 부분을 대어 꼭 맞는지 봤어.」","mis":"M3-1-u2-X16"},{"t":"시우 — 「종이를 반듯하게 두 번 접어 만든 직각을 대어 봤어.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「모눈의 가로줄·세로줄을 따라간 각인지 봤어.」","mis":"M3-1-u2-X16"}],"explanation":["직각인지는 대어 보아야 정확히 알 수 있어요.","삼각자·접은 종이·모눈 줄은 모두 직각을 확인하는 방법이에요.","눈대중은 직각에 가까운 각을 직각으로 잘못 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 각이 직각인지 알아본 방법이 잘못된 친구는 누구인가요?","options":[{"t":"시우 — 「눈으로 보니 반듯해 보여서 직각이라고 했어.」","correct":true,"mis_target":"M3-1-u2-X09"},{"t":"은우 — 「삼각자의 직각 부분을 대어 꼭 맞는지 봤어.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「종이를 반듯하게 두 번 접어 만든 직각을 대어 봤어.」","mis":"M3-1-u2-X16"},{"t":"서윤 — 「모눈의 가로줄·세로줄을 따라간 각인지 봤어.」","mis":"M3-1-u2-X16"}],"explanation":["직각인지는 대어 보아야 정확히 알 수 있어요.","삼각자·접은 종이·모눈 줄은 모두 직각을 확인하는 방법이에요.","눈대중은 직각에 가까운 각을 직각으로 잘못 볼 수 있어요."],"asset":null},{"stem":"이번에는 다른 그림이에요. 각이 직각인지 알아본 방법이 잘못된 친구는 누구인가요?","options":[{"t":"하랑 — 「눈으로 보니 반듯해 보여서 직각이라고 했어.」","correct":true,"mis_target":"M3-1-u2-X09"},{"t":"시우 — 「삼각자의 직각 부분을 대어 꼭 맞는지 봤어.」","mis":"M3-1-u2-X16"},{"t":"서윤 — 「종이를 반듯하게 두 번 접어 만든 직각을 대어 봤어.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「모눈의 가로줄·세로줄을 따라간 각인지 봤어.」","mis":"M3-1-u2-X16"}],"explanation":["직각인지는 대어 보아야 정확히 알 수 있어요.","삼각자·접은 종이·모눈 줄은 모두 직각을 확인하는 방법이에요.","눈대중은 직각에 가까운 각을 직각으로 잘못 볼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=