INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#8','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',4,'sa','auto','직사각형 안에 변과 반듯하게 만나는 선분을 그었어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u2-C4","difficulty":4,"kind":"sa","stem":"직사각형 안에 변과 반듯하게 만나는 선분을 그었어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점마다 둘레를 돌며 삼각자를 대어 봐요.","네 모서리 4개, 가운데 선이 위·아래 변과 만나는 곳에 2개씩 4개.","모두 8개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[60,15],[60,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 직사각형 안에 변과 반듯하게 만나는 선분을 그었어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["점마다 둘레를 돌며 삼각자를 대어 봐요.","네 모서리 4개, 가운데 선이 왼쪽·오른쪽 변과 만나는 곳에 2개씩 4개.","모두 8개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[15,45],[105,45]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 직사각형 안에 변과 반듯하게 만나는 선분을 그었어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점마다 둘레를 돌며 삼각자를 대어 봐요.","네 모서리 4개, 세로선 2개가 위·아래 변과 만나는 곳마다 2개씩 8개.","모두 12개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[45,15],[45,75]],[[75,15],[75,75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#9','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',4,'essay','teacher','삼각자가 없을 때 책상 모서리가 직각인지 알아보는 방법을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C4","difficulty":4,"kind":"essay","stem":"삼각자가 없을 때 책상 모서리가 직각인지 알아보는 방법을 써 보세요.","answer_guide":{"answer":"예: 종이를 반듯하게 한 번 접고, 접힌 선끼리 맞추어 한 번 더 접어 직각을 만든다. 만든 직각의 꼭짓점을 책상 모서리에 맞대어 두 변이 꼭 맞으면 직각이다.","scoring_points":["종이를 반듯하게 두 번 접어 직각을 만든다고 썼는가","꼭짓점과 변을 맞대어 본다고 썼는가","꼭 맞으면 직각이라고 판단했는가"]},"explanation":["종이를 반듯하게 두 번 접으면 직각이 생겨요.","그 직각을 모서리에 맞대어요.","꼭 맞으면 직각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L04_challenge#10','math',3,1,'u2','L04','g3_1_math_u2_L04_challenge','lesson_challenge','M3-1-u2-C4',4,'sa','auto','종이를 반듯하게 두 번 접었다가 펼쳤어요. 접힌 선이 만나는 점 둘레에 생긴 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u2-C4","difficulty":4,"kind":"sa","stem":"종이를 반듯하게 두 번 접었다가 펼쳤어요. 접힌 선이 만나는 점 둘레에 생긴 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 곧은 선이 반듯하게 만나면 만나는 점 둘레가 네 칸으로 나뉘어요.","네 칸의 각은 모두 삼각자에 꼭 맞아요.","그래서 직각은 4개예요."],"variant_rule":{"alt":[{"stem":"십자 모양 길에서 두 길이 반듯하게 만났어요. 두 길이 만나는 점 둘레에 생긴 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 곧은 선이 반듯하게 만나면 만나는 점 둘레가 네 칸으로 나뉘어요.","네 칸의 각은 모두 삼각자에 꼭 맞아요.","그래서 직각은 4개예요."],"asset":null},{"stem":"창문의 가로 창살과 세로 창살이 반듯하게 만났어요. 두 창살이 만나는 점 둘레에 생긴 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 곧은 선이 반듯하게 만나면 만나는 점 둘레가 네 칸으로 나뉘어요.","네 칸의 각은 모두 삼각자에 꼭 맞아요.","그래서 직각은 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_basic#1','math',3,1,'u2','L05','g3_1_math_u2_L05_basic','lesson_basic','M3-1-u2-C5',1,'mc','auto','직각삼각형은 어떤 삼각형인가요?',ARRAY['M3-1-u2-X11','M3-1-u2-X09']::text[],true,'{"seq":1,"concept":"M3-1-u2-C5","difficulty":1,"kind":"mc","stem":"직각삼각형은 어떤 삼각형인가요?","options":[{"t":"한 각이 직각인 삼각형","correct":true},{"t":"세 각이 모두 직각인 삼각형","mis":"M3-1-u2-X11"},{"t":"세 변의 길이가 모두 같은 삼각형","mis":"M3-1-u2-X11"},{"t":"직각이 하나도 없는 삼각형","mis":"M3-1-u2-X09"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"variant_rule":{"alt":[{"stem":"한 각이 ◯◯인 삼각형을 직각삼각형이라고 해요. ◯◯에 알맞은 말은 무엇인가요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"꼭짓점","mis":"M3-1-u2-X06"},{"t":"곧은 선","mis":"M3-1-u2-X01"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"asset":null},{"stem":"직각삼각형에 있는 직각은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M3-1-u2-X11"},{"t":"3개","mis":"M3-1-u2-X11"},{"t":"0개","mis":"M3-1-u2-X09"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
