INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_basic#9','math',3,1,'u2','L05','g3_1_math_u2_L05_basic','lesson_basic','M3-1-u2-C5',2,'ox','auto','직각삼각형의 변은 3개, 꼭짓점도 3개예요.',ARRAY['M3-1-u2-X15']::text[],true,'{"seq":9,"concept":"M3-1-u2-C5","difficulty":2,"kind":"ox","stem":"직각삼각형의 변은 3개, 꼭짓점도 3개예요.","answer":"O","reason_options":[{"t":"직각삼각형도 곧은 선 3개로 둘러싸인 삼각형이라서","correct":true},{"t":"직각이 있는 곳은 꼭짓점으로 세지 않아서","mis":"M3-1-u2-X15"}],"mis":"M3-1-u2-X15","explanation":["직각삼각형도 삼각형이에요.","변 3개, 꼭짓점 3개, 각 3개가 있어요.","그 가운데 한 각이 직각이에요."],"variant_rule":{"alt":[{"stem":"직각삼각형도 삼각형이라 각이 3개 있어요.","answer":"O","reason_options":[{"t":"직각삼각형도 곧은 선 3개로 둘러싸인 삼각형이라서","correct":true},{"t":"직각이 있는 곳은 꼭짓점으로 세지 않아서","mis":"M3-1-u2-X15"}],"explanation":["직각삼각형도 삼각형이에요.","변 3개, 꼭짓점 3개, 각 3개가 있어요.","그 가운데 한 각이 직각이에요."],"asset":null},{"stem":"직각삼각형의 세 각 가운데 한 각만 직각이에요.","answer":"O","reason_options":[{"t":"직각삼각형도 곧은 선 3개로 둘러싸인 삼각형이라서","correct":true},{"t":"직각이 있는 곳은 꼭짓점으로 세지 않아서","mis":"M3-1-u2-X15"}],"explanation":["직각삼각형도 삼각형이에요.","변 3개, 꼭짓점 3개, 각 3개가 있어요.","그 가운데 한 각이 직각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
