INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_challenge#5','math',3,1,'u2','L05','g3_1_math_u2_L05_challenge','lesson_challenge','M3-1-u2-C5',3,'ox','auto','직각삼각형에는 직각이 2개 있을 수도 있어요.',ARRAY['M3-1-u2-X11']::text[],true,'{"seq":5,"concept":"M3-1-u2-C5","difficulty":3,"kind":"ox","stem":"직각삼각형에는 직각이 2개 있을 수도 있어요.","answer":"X","reason_options":[{"t":"직각이 2개면 두 변이 나란히 뻗어 만나지 못해 삼각형이 될 수 없어서","correct":true},{"t":"직각삼각형은 직각이 많을수록 반듯해서","mis":"M3-1-u2-X11"}],"mis":"M3-1-u2-X11","explanation":["삼각형의 한 변 양 끝에서 반듯하게 선을 세워 봐요.","두 선은 나란히 올라가 만나지 않아요.","그래서 삼각형에는 직각이 1개까지만 있어요."],"variant_rule":{"alt":[{"stem":"세 각이 모두 직각인 삼각형도 있어요.","answer":"X","reason_options":[{"t":"직각이 2개면 두 변이 나란히 뻗어 만나지 못해 삼각형이 될 수 없어서","correct":true},{"t":"직각삼각형은 직각이 많을수록 반듯해서","mis":"M3-1-u2-X11"}],"explanation":["삼각형의 한 변 양 끝에서 반듯하게 선을 세워 봐요.","두 선은 나란히 올라가 만나지 않아요.","그래서 삼각형에는 직각이 1개까지만 있어요."],"asset":null},{"stem":"두 각이 직각인 삼각형을 그릴 수 있어요.","answer":"X","reason_options":[{"t":"직각이 2개면 두 변이 나란히 뻗어 만나지 못해 삼각형이 될 수 없어서","correct":true},{"t":"직각삼각형은 직각이 많을수록 반듯해서","mis":"M3-1-u2-X11"}],"explanation":["삼각형의 한 변 양 끝에서 반듯하게 선을 세워 봐요.","두 선은 나란히 올라가 만나지 않아요.","그래서 삼각형에는 직각이 1개까지만 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
