INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_challenge#7','math',3,1,'u2','L05','g3_1_math_u2_L05_challenge','lesson_challenge','M3-1-u2-C5',3,'sa','auto','똑같은 삼각자 4개가 있어요. 삼각자마다 직각삼각형 모양이에요. 삼각자 4개에 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u2-C5","difficulty":3,"kind":"sa","stem":"똑같은 삼각자 4개가 있어요. 삼각자마다 직각삼각형 모양이에요. 삼각자 4개에 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직각삼각형 하나에는 직각이 1개 있어요.","삼각자 4개 — 1개씩 4번.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"똑같은 삼각자 3개가 있어요. 삼각자마다 직각삼각형 모양이에요. 삼각자 3개에 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직각삼각형 하나에는 직각이 1개 있어요.","삼각자 3개 — 1개씩 3번.","모두 3개예요."],"asset":null},{"stem":"똑같은 삼각자 5개가 있어요. 삼각자마다 직각삼각형 모양이에요. 삼각자 5개에 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["직각삼각형 하나에는 직각이 1개 있어요.","삼각자 5개 — 1개씩 5번.","모두 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_challenge#8','math',3,1,'u2','L05','g3_1_math_u2_L05_challenge','lesson_challenge','M3-1-u2-C5',4,'sa','auto','그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u2-C5","difficulty":4,"kind":"sa","stem":"그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 작은 조각 하나로 된 직각삼각형을 세어요.","조각 두 개 이상이 합쳐진 큰 직각삼각형도 찾아요(직각이 있는지 꼭 확인).","크고 작은 직각삼각형은 모두 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[15,15],[105,75]],[[105,15],[15,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 작은 조각 하나로 된 직각삼각형을 세어요.","조각 두 개 이상이 합쳐진 큰 직각삼각형도 찾아요(직각이 있는지 꼭 확인).","크고 작은 직각삼각형은 모두 8개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[30,15],[90,15]],[[90,15],[90,75]],[[90,75],[30,75]],[[30,75],[30,15]],[[30,15],[90,75]],[[90,15],[30,75]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 작은 조각 하나로 된 직각삼각형을 세어요.","조각 두 개 이상이 합쳐진 큰 직각삼각형도 찾아요(직각이 있는지 꼭 확인).","크고 작은 직각삼각형은 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[60,15],[105,60]],[[105,60],[15,60]],[[15,60],[60,15]],[[60,15],[60,60]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_challenge#9','math',3,1,'u2','L05','g3_1_math_u2_L05_challenge','lesson_challenge','M3-1-u2-C5',4,'essay','teacher','모눈 위에 그린 삼각형이 직각삼각형인지 알아보는 방법을 써 보세요. 기울어져 놓인 삼각형이면 어떻게 하는지도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C5","difficulty":4,"kind":"essay","stem":"모눈 위에 그린 삼각형이 직각삼각형인지 알아보는 방법을 써 보세요. 기울어져 놓인 삼각형이면 어떻게 하는지도 써 보세요.","answer_guide":{"answer":"예: 세 꼭짓점에 삼각자의 직각 부분을 차례로 대어 본다. 한 꼭짓점에서 꼭 맞으면 직각삼각형이다. 기울어져 있으면 삼각자를 돌려서 대거나 종이를 돌려 보면 되고, 놓인 방향은 상관없다.","scoring_points":["꼭짓점마다 삼각자(접은 종이)를 대어 본다고 썼는가","한 각이 직각이면 직각삼각형이라고 썼는가","기울어져도 방향과 상관없다고 썼는가"]},"explanation":["세 꼭짓점에 삼각자를 차례로 대어 봐요.","한 각이 꼭 맞으면 직각삼각형이에요.","기울어져 있어도 삼각자를 돌려 대면 돼요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[45,75],[15,15],[105,45]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L05_challenge#10','math',3,1,'u2','L05','g3_1_math_u2_L05_challenge','lesson_challenge','M3-1-u2-C5',4,'mc','auto','직각삼각형에 대한 설명으로 옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 한 각이 직각이다  ㉡ 직각이 2개이다  ㉢ 변이 3개이다  ㉣ 직각이 꼭 아래에 있다',ARRAY['M3-1-u2-X15','M3-1-u2-X11','M3-1-u2-X10']::text[],true,'{"seq":10,"concept":"M3-1-u2-C5","difficulty":4,"kind":"mc","stem":"직각삼각형에 대한 설명으로 옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 한 각이 직각이다  ㉡ 직각이 2개이다  ㉢ 변이 3개이다  ㉣ 직각이 꼭 아래에 있다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠","mis":"M3-1-u2-X15"},{"t":"㉠, ㉡, ㉢","mis":"M3-1-u2-X11"},{"t":"㉠, ㉢, ㉣","mis":"M3-1-u2-X10"}],"explanation":["직각삼각형 = 한 각이 직각인 삼각형(변 3개·꼭짓점 3개·각 3개).","직각은 1개 — 방향은 상관없어요.","옳은 것은 ㉠, ㉢예요."],"variant_rule":{"alt":[{"stem":"직각삼각형에 대한 설명으로 옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 직각이 1개이다  ㉡ 꼭짓점이 4개이다  ㉢ 기울여 놓아도 직각삼각형이다  ㉣ 세 각이 모두 직각이다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠","mis":"M3-1-u2-X10"},{"t":"㉠, ㉡","mis":"M3-1-u2-X15"},{"t":"㉢, ㉣","mis":"M3-1-u2-X11"}],"explanation":["직각삼각형 = 한 각이 직각인 삼각형(변 3개·꼭짓점 3개·각 3개).","직각은 1개 — 방향은 상관없어요.","옳은 것은 ㉠, ㉢예요."],"asset":null},{"stem":"직각삼각형에 대한 설명으로 옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 삼각자 모양이다  ㉡ 직각이 없다  ㉢ 각이 3개이다  ㉣ 세 변이 모두 같아야 한다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M3-1-u2-X09"},{"t":"㉢, ㉣","mis":"M3-1-u2-X11"},{"t":"㉠","mis":"M3-1-u2-X15"}],"explanation":["직각삼각형 = 한 각이 직각인 삼각형(변 3개·꼭짓점 3개·각 3개).","직각은 1개 — 방향은 상관없어요.","옳은 것은 ㉠, ㉢예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_basic#1','math',3,1,'u2','L06','g3_1_math_u2_L06_basic','lesson_basic','M3-1-u2-C6',1,'mc','auto','직사각형은 어떤 사각형인가요?',ARRAY['M3-1-u2-X12','M3-1-u2-X14','M3-1-u2-X09']::text[],true,'{"seq":1,"concept":"M3-1-u2-C6","difficulty":1,"kind":"mc","stem":"직사각형은 어떤 사각형인가요?","options":[{"t":"네 각이 모두 직각인 사각형","correct":true},{"t":"직각이 한 개 있는 사각형","mis":"M3-1-u2-X12"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M3-1-u2-X14"},{"t":"직각이 하나도 없는 사각형","mis":"M3-1-u2-X09"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"variant_rule":{"alt":[{"stem":"직사각형은 네 각이 모두 ◯◯인 사각형이에요. ◯◯에 알맞은 말은 무엇인가요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"곧은 선","mis":"M3-1-u2-X01"},{"t":"꼭짓점","mis":"M3-1-u2-X06"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"asset":null},{"stem":"네 각이 모두 직각인 사각형의 이름은 무엇인가요?","options":[{"t":"직사각형","correct":true},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"삼각형","mis":"M3-1-u2-X12"},{"t":"선분","mis":"M3-1-u2-X02"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
