INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_basic#7','math',3,1,'u2','L06','g3_1_math_u2_L06_basic','lesson_basic','M3-1-u2-C7',2,'sa','auto','한 변이 6 cm인 정사각형이 있어요. 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u2-C7","difficulty":2,"kind":"sa","stem":"한 변이 6 cm인 정사각형이 있어요. 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","6 cm가 4개 — 6 + 6 + 6 + 6.","24 cm예요."],"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형이 있어요. 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","8 cm가 4개 — 8 + 8 + 8 + 8.","32 cm예요."],"asset":null},{"stem":"한 변이 9 cm인 정사각형이 있어요. 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","9 cm가 4개 — 9 + 9 + 9 + 9.","36 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
