INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#5','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',3,'mc','auto','가로 9 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?',ARRAY['M3-1-u2-X14','M3-1-u2-X11','M3-1-u2-X15']::text[],true,'{"seq":5,"concept":"M3-1-u2-C7","difficulty":3,"kind":"mc","stem":"가로 9 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 6 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 6 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 9 − 6 = 3 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[93.75,15]],[[93.75,15],[93.75,67.5]],[[93.75,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 6 cm, 세로 6 cm인 정사각형","correct":true},{"t":"가로 12 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 12 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 12 − 6 = 6 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같아 — 정사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[120.0,15]],[[120.0,15],[120.0,67.5]],[[120.0,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false}},{"stem":"가로 10 cm, 세로 7 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 7 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 7 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 7 cm, 세로 7 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 7 cm예요.","남은 종이는 가로 10 − 7 = 3 cm, 세로 7 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[102.5,15]],[[102.5,15],[102.5,76.25]],[[102.5,76.25],[15,76.25]],[[15,76.25],[15,15]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#6','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',3,'ox','auto','네 변의 길이가 모두 같은 사각형은 모두 정사각형이에요.',ARRAY['M3-1-u2-X12']::text[],true,'{"seq":6,"concept":"M3-1-u2-C7","difficulty":3,"kind":"ox","stem":"네 변의 길이가 모두 같은 사각형은 모두 정사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"mis":"M3-1-u2-X12","explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 사각형은 네 변의 길이가 모두 같으니 정사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false}},{"stem":"네 변의 길이가 같기만 하면 정사각형이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#7','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',3,'sa','auto','철사 36 cm를 남김없이 모두 써서 정사각형 하나를 만들었어요. 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u2-C7","difficulty":3,"kind":"sa","stem":"철사 36 cm를 남김없이 모두 써서 정사각형 하나를 만들었어요. 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","같은 수를 4번 더해 36이 되는 수를 찾아요.","9 + 9 + 9 + 9 = 36 — 한 변은 9 cm예요."],"variant_rule":{"alt":[{"stem":"철사 28 cm를 남김없이 모두 써서 정사각형 하나를 만들었어요. 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","같은 수를 4번 더해 28이 되는 수를 찾아요.","7 + 7 + 7 + 7 = 28 — 한 변은 7 cm예요."],"asset":null},{"stem":"철사 44 cm를 남김없이 모두 써서 정사각형 하나를 만들었어요. 정사각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["정사각형은 네 변의 길이가 모두 같아요.","같은 수를 4번 더해 44가 되는 수를 찾아요.","11 + 11 + 11 + 11 = 44 — 한 변은 11 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#8','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',4,'mc','auto','옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 정사각형은 직사각형이다  ㉡ 직사각형은 정사각형이다  ㉢ 정사각형은 네 각이 모두 직각이다  ㉣ 직사각형은 네 변의 길이가 모두 같다',ARRAY['M3-1-u2-X13','M3-1-u2-X14']::text[],true,'{"seq":8,"concept":"M3-1-u2-C7","difficulty":4,"kind":"mc","stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 정사각형은 직사각형이다  ㉡ 직사각형은 정사각형이다  ㉢ 정사각형은 네 각이 모두 직각이다  ㉣ 직사각형은 네 변의 길이가 모두 같다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉢","mis":"M3-1-u2-X13"},{"t":"㉠, ㉡, ㉢","mis":"M3-1-u2-X14"},{"t":"㉡, ㉣","mis":"M3-1-u2-X14"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"variant_rule":{"alt":[{"stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 직사각형은 네 각이 모두 직각이다  ㉡ 정사각형은 직사각형이 아니다  ㉢ 기울어진 직사각형도 직사각형이다  ㉣ 직각이 2개인 사각형은 직사각형이다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠","mis":"M3-1-u2-X10"},{"t":"㉠, ㉡, ㉢","mis":"M3-1-u2-X13"},{"t":"㉠, ㉢, ㉣","mis":"M3-1-u2-X12"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"asset":null},{"stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 정사각형은 네 변의 길이가 같다  ㉡ 네 변의 길이가 같으면 모두 정사각형이다  ㉢ 정사각형은 직사각형이다  ㉣ 직사각형은 직각이 3개이다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M3-1-u2-X12"},{"t":"㉠","mis":"M3-1-u2-X13"},{"t":"㉢, ㉣","mis":"M3-1-u2-X12"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#9','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',4,'essay','teacher','「정사각형은 직사각형이지만, 직사각형은 정사각형이 아닐 수도 있어요.」 이 말이 맞는 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C7","difficulty":4,"kind":"essay","stem":"「정사각형은 직사각형이지만, 직사각형은 정사각형이 아닐 수도 있어요.」 이 말이 맞는 까닭을 써 보세요.","answer_guide":{"answer":"예: 직사각형은 네 각이 모두 직각인 사각형이다. 정사각형은 네 각이 모두 직각이므로 직사각형이다. 하지만 직사각형은 네 변의 길이가 같지 않을 수 있어서(예: 가로 6 cm, 세로 4 cm) 정사각형이 아닐 수 있다.","scoring_points":["직사각형의 조건(네 각이 직각)을 썼는가","정사각형이 그 조건을 만족해 직사각형이라고 썼는가","네 변이 같지 않은 직사각형이 있어 정사각형이 아닐 수 있다고 썼는가"]},"explanation":["직사각형: 네 각이 모두 직각.","정사각형도 네 각이 모두 직각 → 직사각형.","변의 길이가 다른 직사각형은 정사각형이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L06_challenge#10','math',3,1,'u2','L06','g3_1_math_u2_L06_challenge','lesson_challenge','M3-1-u2-C7',4,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u2-C7","difficulty":4,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 5 cm예요.","5 + 5 + 5 + 5 = 20 cm예요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 4 cm예요.","4 + 4 + 4 + 4 = 16 cm예요."],"asset":null},{"stem":"가로 7 cm, 세로 10 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 7 cm예요.","7 + 7 + 7 + 7 = 28 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_basic#1','math',3,1,'u2','L07','g3_1_math_u2_L07_basic','lesson_basic','M3-1-u2-C8',1,'mc','auto','고양이 그림에서 얼굴은 무슨 도형인가요?',ARRAY['M3-1-u2-X13','M3-1-u2-X09','M3-1-u2-X01']::text[],true,'{"seq":1,"concept":"M3-1-u2-C8","difficulty":1,"kind":"mc","stem":"고양이 그림에서 얼굴은 무슨 도형인가요?","options":[{"t":"정사각형","correct":true},{"t":"직사각형만","mis":"M3-1-u2-X13"},{"t":"직각삼각형","mis":"M3-1-u2-X09"},{"t":"원","mis":"M3-1-u2-X01"}],"explanation":["얼굴 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","네 각이 모두 직각이고 네 변의 길이가 모두 같아요 — 정사각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":150,"h":120,"grid":15,"poly":[[[30,30],[105,30],[105,105],[30,105]],[[30,30],[30,7.5],[52.5,30]],[[105,30],[105,7.5],[82.5,30]],[[45,45],[60,45],[60,67.5],[45,67.5]],[[75,45],[90,45],[90,67.5],[75,67.5]]],"seg":[[[7.5,75],[45,82.5]],[[7.5,97.5],[45,90]],[[90,82.5],[127.5,75]],[[90,90],[127.5,97.5]]],"cap":"고양이"}],"tag":false},"variant_rule":{"alt":[{"stem":"고양이 그림에서 귀는 무슨 도형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"정사각형","mis":"M3-1-u2-X14"},{"t":"직사각형","mis":"M3-1-u2-X14"},{"t":"삼각형","mis":"M3-1-u2-X09"}],"explanation":["귀 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","한 각이 직각인 삼각형 — 직각삼각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":150,"h":120,"grid":15,"poly":[[[30,30],[105,30],[105,105],[30,105]],[[30,30],[30,7.5],[52.5,30]],[[105,30],[105,7.5],[82.5,30]],[[45,45],[60,45],[60,67.5],[45,67.5]],[[75,45],[90,45],[90,67.5],[75,67.5]]],"seg":[[[7.5,75],[45,82.5]],[[7.5,97.5],[45,90]],[[90,82.5],[127.5,75]],[[90,90],[127.5,97.5]]],"cap":"고양이"}],"tag":false}},{"stem":"고양이 그림에서 눈은 무슨 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X09"},{"t":"삼각형","mis":"M3-1-u2-X09"}],"explanation":["눈 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","네 각이 모두 직각이지만 네 변의 길이가 모두 같지는 않아요 — 직사각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":150,"h":120,"grid":15,"poly":[[[30,30],[105,30],[105,105],[30,105]],[[30,30],[30,7.5],[52.5,30]],[[105,30],[105,7.5],[82.5,30]],[[45,45],[60,45],[60,67.5],[45,67.5]],[[75,45],[90,45],[90,67.5],[75,67.5]]],"seg":[[[7.5,75],[45,82.5]],[[7.5,97.5],[45,90]],[[90,82.5],[127.5,75]],[[90,90],[127.5,97.5]]],"cap":"고양이"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
