INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#3','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',3,'mc','auto','정사각형 하나에 선분 2개를 그어 똑같은 직각삼각형 4개로 나누려면 어떻게 그어야 하나요?',ARRAY['M3-1-u2-X14','M3-1-u2-X12','M3-1-u2-X15']::text[],true,'{"seq":3,"concept":"M3-1-u2-C8","difficulty":3,"kind":"mc","stem":"정사각형 하나에 선분 2개를 그어 똑같은 직각삼각형 4개로 나누려면 어떻게 그어야 하나요?","options":[{"t":"마주 보는 꼭짓점끼리 잇는 선분 2개를 긋는다","correct":true},{"t":"가로 가운데와 세로 가운데에 선분을 긋는다","mis":"M3-1-u2-X14"},{"t":"가로로 선분 2개를 긋는다","mis":"M3-1-u2-X12"},{"t":"한 꼭짓점에서 선분 2개를 긋는다","mis":"M3-1-u2-X15"}],"explanation":["선분을 그은 뒤 생기는 조각을 떠올려 봐요.","마주 보는 꼭짓점끼리 잇는 선분 2개를 긋는다 — 그러면 원하는 도형이 생겨요.","다른 방법은 조각의 모양이나 수가 달라져요."],"variant_rule":{"alt":[{"stem":"정사각형 하나에 선분 2개를 그어 똑같은 정사각형 4개로 나누려면 어떻게 그어야 하나요?","options":[{"t":"가로 가운데와 세로 가운데에 선분을 하나씩 긋는다","correct":true},{"t":"마주 보는 꼭짓점끼리 잇는 선분 2개를 긋는다","mis":"M3-1-u2-X11"},{"t":"가로로 선분 2개를 긋는다","mis":"M3-1-u2-X14"},{"t":"세로로 선분 2개를 긋는다","mis":"M3-1-u2-X14"}],"explanation":["선분을 그은 뒤 생기는 조각을 떠올려 봐요.","가로 가운데와 세로 가운데에 선분을 하나씩 긋는다 — 그러면 원하는 도형이 생겨요.","다른 방법은 조각의 모양이나 수가 달라져요."],"asset":null},{"stem":"직사각형 하나에 선분 1개를 그어 똑같은 직각삼각형 2개로 나누려면 어떻게 그어야 하나요?","options":[{"t":"마주 보는 꼭짓점끼리 잇는 선분을 긋는다","correct":true},{"t":"가로 가운데에 선분을 긋는다","mis":"M3-1-u2-X14"},{"t":"세로 가운데에 선분을 긋는다","mis":"M3-1-u2-X14"},{"t":"한 변의 가운데와 꼭짓점을 잇는다","mis":"M3-1-u2-X15"}],"explanation":["선분을 그은 뒤 생기는 조각을 떠올려 봐요.","마주 보는 꼭짓점끼리 잇는 선분을 긋는다 — 그러면 원하는 도형이 생겨요.","다른 방법은 조각의 모양이나 수가 달라져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#4','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',3,'sa','auto','정사각형 2개, 직각삼각형 3개, 직사각형 1개로 그림을 그렸어요. 쓰인 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u2-C8","difficulty":3,"kind":"sa","stem":"정사각형 2개, 직각삼각형 3개, 직사각형 1개로 그림을 그렸어요. 쓰인 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["정사각형·직사각형은 꼭짓점 4개, 직각삼각형은 3개예요.","정사각형 2개: 8, 직각삼각형 3개: 9, 직사각형 1개: 4.","8 + 9 + 4 = 21개예요."],"variant_rule":{"alt":[{"stem":"정사각형 1개, 직각삼각형 2개, 직사각형 3개로 그림을 그렸어요. 쓰인 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["정사각형·직사각형은 꼭짓점 4개, 직각삼각형은 3개예요.","정사각형 1개: 4, 직각삼각형 2개: 6, 직사각형 3개: 12.","4 + 6 + 12 = 22개예요."],"asset":null},{"stem":"정사각형 3개, 직각삼각형 1개, 직사각형 2개로 그림을 그렸어요. 쓰인 도형의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["정사각형·직사각형은 꼭짓점 4개, 직각삼각형은 3개예요.","정사각형 3개: 12, 직각삼각형 1개: 3, 직사각형 2개: 8.","12 + 3 + 8 = 23개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
