INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#6','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',3,'sa','auto','창살로 나뉜 창문이에요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요. (정사각형도 직사각형으로 세어요.)','{}'::text[],true,'{"seq":6,"concept":"M3-1-u2-C8","difficulty":3,"kind":"sa","stem":"창살로 나뉜 창문이에요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요. (정사각형도 직사각형으로 세어요.)","answer":["9"],"explanation":["작은 칸 하나짜리부터 세어요.","칸 두 개, 세 개… 를 합친 직사각형, 창문 전체까지 차례로 세어요.","모두 9개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15.0,15],[15.0,75]],[[52.5,15],[52.5,75]],[[90.0,15],[90.0,75]],[[15,15],[90.0,15]],[[15,45],[90.0,45]],[[15,75],[90.0,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 창살로 나뉜 창문이에요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요. (정사각형도 직사각형으로 세어요.)","answer":["6"],"explanation":["작은 칸 하나짜리부터 세어요.","칸 두 개, 세 개… 를 합친 직사각형, 창문 전체까지 차례로 세어요.","모두 6개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[15,45]],[[45,15],[45,45]],[[75,15],[75,45]],[[105,15],[105,45]],[[15,15],[105,15]],[[15,45],[105,45]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 창살로 나뉜 창문이에요. 그림에서 찾을 수 있는 크고 작은 직사각형은 모두 몇 개인가요? 숫자로 쓰세요. (정사각형도 직사각형으로 세어요.)","answer":["18"],"explanation":["작은 칸 하나짜리부터 세어요.","칸 두 개, 세 개… 를 합친 직사각형, 창문 전체까지 차례로 세어요.","모두 18개예요."],"asset":{"type":"geo","items":[{"w":120,"h":97.5,"seg":[[[15.0,15],[15.0,82.5]],[[52.5,15],[52.5,82.5]],[[90.0,15],[90.0,82.5]],[[15,15.0],[90.0,15.0]],[[15,37.5],[90.0,37.5]],[[15,60.0],[90.0,60.0]],[[15,82.5],[90.0,82.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payl