INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#7','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',3,'ox','auto','선분 4개로 둘러싸인 도형은 언제나 직사각형이에요.',ARRAY['M3-1-u2-X12']::text[],true,'{"seq":7,"concept":"M3-1-u2-C8","difficulty":3,"kind":"ox","stem":"선분 4개로 둘러싸인 도형은 언제나 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"mis":"M3-1-u2-X12","explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[105,15],[90,75],[15,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"꼭짓점이 4개인 도형은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[45,15],[75,15],[105,75],[15,75]]]}],"tag":false}},{"stem":"사각형에 직각이 하나 있으면 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[75,15],[105,75],[15,60]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#8','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',4,'sa','auto','정사각형 모양 연에 두 대각선을 그었어요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u2-C8","difficulty":4,"kind":"sa","stem":"정사각형 모양 연에 두 대각선을 그었어요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["작은 삼각형 조각부터 직각이 있는지 확인하며 세어요.","조각 두 개를 합친 큰 삼각형도 찾아 직각이 있는지 봐요(직각이 없는 것은 빼요).","크고 작은 직각삼각형은 8개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[30,15],[90,15]],[[90,15],[90,75]],[[90,75],[30,75]],[[30,75],[30,15]],[[30,15],[90,75]],[[90,15],[30,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 모양 액자에 두 대각선을 그었어요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["작은 삼각형 조각부터 직각이 있는지 확인하며 세어요.","조각 두 개를 합친 큰 삼각형도 찾아 직각이 있는지 봐요(직각이 없는 것은 빼요).","크고 작은 직각삼각형은 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[15,15],[105,75]],[[105,15],[15,75]]]}],"tag":false}},{"stem":"직사각형 모양 종이에 선분 2개를 그었어요. 그림에서 찾을 수 있는 크고 작은 직각삼각형은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["작은 삼각형 조각부터 직각이 있는지 확인하며 세어요.","조각 두 개를 합친 큰 삼각형도 찾아 직각이 있는지 봐요(직각이 없는 것은 빼요).","크고 작은 직각삼각형은 4개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[15,15],[105,15]],[[105,15],[105,75]],[[105,75],[15,75]],[[15,75],[15,15]],[[15,15],[105,75]],[[60,15],[60,75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#9','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',4,'essay','teacher','배운 평면도형(선분·직각삼각형·직사각형·정사각형)으로 그리고 싶은 그림을 하나 정하고, 어느 부분을 어떤 도형으로 몇 개 그릴지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u2-C8","difficulty":4,"kind":"essay","stem":"배운 평면도형(선분·직각삼각형·직사각형·정사각형)으로 그리고 싶은 그림을 하나 정하고, 어느 부분을 어떤 도형으로 몇 개 그릴지 써 보세요.","answer_guide":{"answer":"예: 자동차를 그린다. 몸체는 직사각형 1개, 창문은 정사각형 2개, 앞 유리는 직각삼각형 1개, 바퀴 축은 선분 2개로 그린다. 정사각형은 네 각이 직각이고 네 변이 같게, 직각삼각형은 한 각이 직각이 되게 그린다.","scoring_points":["그릴 그림과 부분을 정했는가","부분마다 도형 이름을 바르게 썼는가","도형의 개수나 성질(직각·같은 변)을 함께 썼는가"]},"explanation":["그림을 부분으로 나눠요.","부분마다 알맞은 도형 이름과 개수를 정해요.","도형의 성질(직각·변의 길이)에 맞게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_L07_challenge#10','math',3,1,'u2','L07','g3_1_math_u2_L07_challenge','lesson_challenge','M3-1-u2-C8',4,'mc','auto','모눈 위의 세 점 ㄱ, ㄴ, ㄷ과 어느 점을 이으면 직사각형이 되나요?',ARRAY['M3-1-u2-X12','M3-1-u2-X10']::text[],true,'{"seq":10,"concept":"M3-1-u2-C8","difficulty":4,"kind":"mc","stem":"모눈 위의 세 점 ㄱ, ㄴ, ㄷ과 어느 점을 이으면 직사각형이 되나요?","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㅁ","mis":"M3-1-u2-X12"},{"t":"점 ㅂ","mis":"M3-1-u2-X12"},{"t":"어느 점도 안 돼요","mis":"M3-1-u2-X10"}],"explanation":["선분 ㄱㄴ, 선분 ㄴㄷ이 반듯하게 만나는지 먼저 봐요.","점 ㄷ에서 선분 ㄱㄴ과 나란하게, 점 ㄱ에서 선분 ㄴㄷ과 나란하게 모눈 칸을 같은 만큼 옮기면 점 ㄹ에서 만나요.","그러면 네 각이 모두 직각이 돼요."],"asset":{"type":"geo","items":[{"w":120,"h":97.5,"grid":15,"pts":{"ㄱ":[30,15],"ㄴ":[90,45],"ㄷ":[75,75],"ㄹ":[15,45],"ㅁ":[45,82.5],"ㅂ":[7.5,75]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 모눈 위의 세 점 ㄱ, ㄴ, ㄷ과 어느 점을 이으면 직사각형이 되나요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㄹ","mis":"M3-1-u2-X12"},{"t":"점 ㅁ","mis":"M3-1-u2-X12"},{"t":"어느 점도 안 돼요","mis":"M3-1-u2-X10"}],"explanation":["선분 ㄱㄴ, 선분 ㄴㄷ이 반듯하게 만나는지 먼저 봐요.","점 ㄷ에서 선분 ㄱㄴ과 나란하게, 점 ㄱ에서 선분 ㄴㄷ과 나란하게 모눈 칸을 같은 만큼 옮기면 점 ㅂ에서 만나요.","그러면 네 각이 모두 직각이 돼요."],"asset":{"type":"geo","items":[{"w":120,"h":97.5,"grid":15,"pts":{"ㄱ":[15,30],"ㄴ":[75,30],"ㄷ":[75,75],"ㄹ":[45,90],"ㅁ":[7.5,49.5],"ㅂ":[15,75]},"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 모눈 위의 세 점 ㄱ, ㄴ, ㄷ과 어느 점을 이으면 직사각형이 되나요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M3-1-u2-X12"},{"t":"점 ㅂ","mis":"M3-1-u2-X12"},{"t":"어느 점도 안 돼요","mis":"M3-1-u2-X10"}],"explanation":["선분 ㄱㄴ, 선분 ㄴㄷ이 반듯하게 만나는지 먼저 봐요.","점 ㄷ에서 선분 ㄱㄴ과 나란하게, 점 ㄱ에서 선분 ㄴㄷ과 나란하게 모눈 칸을 같은 만큼 옮기면 점 ㅁ에서 만나요.","그러면 네 각이 모두 직각이 돼요."],"asset":{"type":"geo","items":[{"w":120,"h":97.5,"grid":15,"pts":{"ㄱ":[45,15],"ㄴ":[90,60],"ㄷ":[60,90],"ㄹ":[37.5,64.5]