INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_a#2','math',3,1,'u2','','g3_1_math_u2_review_a','unit_review','M3-1-u2-C2',1,'mc','auto','한 점에서 시작하여 한쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?',ARRAY['M3-1-u2-X02','M3-1-u2-X01']::text[],true,'{"seq":2,"concept":"M3-1-u2-C2","difficulty":1,"kind":"mc","stem":"한 점에서 시작하여 한쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"반직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["시작하는 끝 하나만 있는 곧은 선이 반직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"variant_rule":{"alt":[{"stem":"두 점을 지나 양쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 없는 곧은 선이 직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null},{"stem":"두 점을 곧게 이은 선을 무엇이라고 하나요?","options":[{"t":"선분","correct":true},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["두 끝이 있는 곧은 선이 선분이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
