INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_a#15','math',3,1,'u2','','g3_1_math_u2_review_a','unit_review','M3-1-u2-C7',2,'ox','auto','정사각형도 네 각이 모두 직각이니 직사각형이에요.',ARRAY['M3-1-u2-X13']::text[],true,'{"seq":15,"concept":"M3-1-u2-C7","difficulty":2,"kind":"ox","stem":"정사각형도 네 각이 모두 직각이니 직사각형이에요.","answer":"O","reason_options":[{"t":"정사각형도 네 각이 모두 직각인 사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 직사각형이 될 수 없어서","mis":"M3-1-u2-X13"}],"mis":"M3-1-u2-X13","explanation":["직사각형의 조건은 네 각이 모두 직각인 것뿐이에요.","정사각형은 네 각이 모두 직각 — 조건을 만족해요.","그래서 정사각형은 직사각형이에요(거꾸로는 아니에요)."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[45,30],[90,30],[90,75],[45,75]]],"tick":[[[45,30],[90,30],1],[[90,30],[90,75],1],[[90,75],[45,75],1],[[45,75],[45,30],1]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형 모양 색종이는 직사각형 모양 색종이라고도 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형도 네 각이 모두 직각인 사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 직사각형이 될 수 없어서","mis":"M3-1-u2-X13"}],"explanation":["직사각형의 조건은 네 각이 모두 직각인 것뿐이에요.","정사각형은 네 각이 모두 직각 — 조건을 만족해요.","그래서 정사각형은 직사각형이에요(거꾸로는 아니에요)."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[90,15],[90,75],[30,75]]],"tick":[[[30,15],[90,15],1],[[90,15],[90,75],1],[[90,75],[30,75],1],[[30,75],[30,15],1]]}],"tag":false}},{"stem":"정사각형은 직사각형이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형도 네 각이 모두 직각인 사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 직사각형이 될 수 없어서","mis":"M3-1-u2-X13"}],"explanation":["직사각형의 조건은 네 각이 모두 직각인 것뿐이에요.","정사각형은 네 각이 모두 직각 — 조건을 만족해요.","그래서 정사각형은 직사각형이에요(거꾸로는 아니에요)."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[90,15],[90,75],[30,75]]],"tick":[[[30,15],[90,15],1],[[90,15],[90,75],1],[[90,75],[30,75],1],[[30,75],[30,15],1]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXC