INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_a#23','math',3,1,'u2','','g3_1_math_u2_review_a','unit_review','M3-1-u2-C3',4,'sa','auto','사각형 ㅁㅂㅅㅇ에 선분 ㅁㅅ을 그었어요. 점 ㅁ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M3-1-u2-C3","difficulty":4,"kind":"sa","stem":"사각형 ㅁㅂㅅㅇ에 선분 ㅁㅅ을 그었어요. 점 ㅁ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㅁ에서 변 ㅁㅂ, 선분 ㅁㅅ, 변 ㅁㅇ 세 선이 나가요.","작은 각 각 ㅂㅁㅅ, 각 ㅅㅁㅇ — 2개.","두 각을 합친 큰 각 ㅂㅁㅇ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㅁ":[30,15],"ㅂ":[90,15],"ㅅ":[90,75],"ㅇ":[30,75]},"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[["ㅁ","ㅅ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ에 선분 ㄱㄷ을 그었어요. 점 ㄱ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄱ에서 변 ㄱㄴ, 선분 ㄱㄷ, 변 ㄱㄹ 세 선이 나가요.","작은 각 각 ㄴㄱㄷ, 각 ㄷㄱㄹ — 2개.","두 각을 합친 큰 각 ㄴㄱㄹ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㄱ":[30,15],"ㄴ":[105,15],"ㄷ":[90,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ에 선분 ㄱㄷ을 그었어요. 점 ㄱ을 꼭짓점으로 하는 각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["점 ㄱ에서 변 ㄱㄴ, 선분 ㄱㄷ, 변 ㄱㄹ 세 선이 나가요.","작은 각 각 ㄴㄱㄷ, 각 ㄷㄱㄹ — 2개.","두 각을 합친 큰 각 ㄴㄱㄹ까지 모두 3개예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[105,15],"ㄷ":[105,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_a#24','math',3,1,'u2','','g3_1_math_u2_review_a','unit_review','M3-1-u2-C7',4,'mc','auto','옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 직사각형은 네 각이 모두 직각이다  ㉡ 정사각형은 직사각형이 아니다  ㉢ 기울어진 직사각형도 직사각형이다  ㉣ 직각이 2개인 사각형은 직사각형이다',ARRAY['M3-1-u2-X10','M3-1-u2-X13','M3-1-u2-X12']::text[],true,'{"seq":24,"concept":"M3-1-u2-C7","difficulty":4,"kind":"mc","stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 직사각형은 네 각이 모두 직각이다  ㉡ 정사각형은 직사각형이 아니다  ㉢ 기울어진 직사각형도 직사각형이다  ㉣ 직각이 2개인 사각형은 직사각형이다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠","mis":"M3-1-u2-X10"},{"t":"㉠, ㉡, ㉢","mis":"M3-1-u2-X13"},{"t":"㉠, ㉢, ㉣","mis":"M3-1-u2-X12"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"variant_rule":{"alt":[{"stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 정사각형은 네 변의 길이가 같다  ㉡ 네 변의 길이가 같으면 모두 정사각형이다  ㉢ 정사각형은 직사각형이다  ㉣ 직사각형은 직각이 3개이다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉡","mis":"M3-1-u2-X12"},{"t":"㉠","mis":"M3-1-u2-X13"},{"t":"㉢, ㉣","mis":"M3-1-u2-X12"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"asset":null},{"stem":"옳은 것을 모두 고른 것은 어느 것인가요?  ㉠ 정사각형은 직사각형이다  ㉡ 직사각형은 정사각형이다  ㉢ 정사각형은 네 각이 모두 직각이다  ㉣ 직사각형은 네 변의 길이가 모두 같다","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉢","mis":"M3-1-u2-X13"},{"t":"㉠, ㉡, ㉢","mis":"M3-1-u2-X14"},{"t":"㉡, ㉣","mis":"M3-1-u2-X14"}],"explanation":["직사각형 = 네 각이 모두 직각.","정사각형 = 네 각이 모두 직각 + 네 변이 모두 같음 — 그래서 정사각형은 직사각형이에요.","옳은 것은 ㉠, ㉢예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_a#25','math',3,1,'u2','','g3_1_math_u2_review_a','unit_review','M3-1-u2-C2',4,'essay','teacher','반직선 ㄱㄴ과 반직선 ㄴㄱ이 같은지 다른지 쓰고, 그 까닭을 그림을 떠올리며 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u2-C2","difficulty":4,"kind":"essay","stem":"반직선 ㄱㄴ과 반직선 ㄴㄱ이 같은지 다른지 쓰고, 그 까닭을 그림을 떠올리며 설명해 보세요.","answer_guide":{"answer":"예: 다르다. 반직선 ㄱㄴ은 점 ㄱ에서 시작해 점 ㄴ 쪽으로 끝없이 늘어나고, 반직선 ㄴㄱ은 점 ㄴ에서 시작해 점 ㄱ 쪽으로 끝없이 늘어난다. 시작점과 늘어나는 쪽이 다르므로 다른 반직선이다.","scoring_points":["다르다고 판단했는가","두 반직선의 시작점을 바르게 썼는가","늘어나는 쪽이 다르다는 까닭을 썼는가"]},"explanation":["반직선은 시작점을 먼저 읽어요.","반직선 ㄱㄴ: 점 ㄱ에서 ㄴ 쪽 · 반직선 ㄴㄱ: 점 ㄴ에서 ㄱ 쪽.","시작점과 방향이 달라 다른 반직선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#1','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C2',1,'mc','auto','이 곧은 선의 이름은 무엇인가요?',ARRAY['M3-1-u2-X02']::text[],true,'{"seq":1,"concept":"M3-1-u2-C2","difficulty":1,"kind":"mc","stem":"이 곧은 선의 이름은 무엇인가요?","options":[{"t":"직선 ㄴㄷ","correct":true},{"t":"선분 ㄴㄷ","mis":"M3-1-u2-X02"},{"t":"반직선 ㄴㄷ","mis":"M3-1-u2-X02"},{"t":"반직선 ㄷㄴ","mis":"M3-1-u2-X02"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㄴ과 점 ㄷ을 지나 양쪽으로 끝없이 늘어나요 — 직선이에요.","직선은 직선 ㄴㄷ, 직선 ㄷㄴ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄴ":[45,45],"ㄷ":[97.5,45]},"line":[["ㄴ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 곧은 선의 이름은 무엇인가요?","options":[{"t":"직선 ㄹㅁ","correct":true},{"t":"선분 ㄹㅁ","mis":"M3-1-u2-X02"},{"t":"반직선 ㄹㅁ","mis":"M3-1-u2-X02"},{"t":"반직선 ㅁㄹ","mis":"M3-1-u2-X02"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㄹ과 점 ㅁ을 지나 양쪽으로 끝없이 늘어나요 — 직선이에요.","직선은 직선 ㄹㅁ, 직선 ㅁㄹ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄹ":[45,60],"ㅁ":[97.5,30]},"line":[["ㄹ","ㅁ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 곧은 선의 이름은 무엇인가요?","options":[{"t":"직선 ㅂㅅ","correct":true},{"t":"선분 ㅂㅅ","mis":"M3-1-u2-X02"},{"t":"반직선 ㅂㅅ","mis":"M3-1-u2-X02"},{"t":"반직선 ㅅㅂ","mis":"M3-1-u2-X02"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㅂ과 점 ㅅ을 지나 양쪽으로 끝없이 늘어나요 — 직선이에요.","직선은 직선 ㅂㅅ, 직선 ㅅㅂ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅂ":[45,30],"ㅅ":[97.5,60]},"line":[["ㅂ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#2','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C2',1,'mc','auto','두 점을 지나 양쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?',ARRAY['M3-1-u2-X02','M3-1-u2-X01']::text[],true,'{"seq":2,"concept":"M3-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 점을 지나 양쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 없는 곧은 선이 직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"variant_rule":{"alt":[{"stem":"두 점을 곧게 이은 선을 무엇이라고 하나요?","options":[{"t":"선분","correct":true},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["두 끝이 있는 곧은 선이 선분이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null},{"stem":"한 점에서 시작하여 한쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"반직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["시작하는 끝 하나만 있는 곧은 선이 반직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#3','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C3',1,'mc','auto','그림의 각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u2-X05']::text[],true,'{"seq":3,"concept":"M3-1-u2-C3","difficulty":1,"kind":"mc","stem":"그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㄴㄷㄹ","correct":true},{"t":"각 ㄴㄹㄷ","mis":"M3-1-u2-X05"},{"t":"각 ㄷㄴㄹ","mis":"M3-1-u2-X05"},{"t":"각 ㄷㄹㄴ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㄷ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㄴㄷㄹ 또는 각 ㄹㄷㄴ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄴ":[120.0,75.0],"ㄷ":[22.5,75],"ㄹ":[67.5,7.5]},"ray":[["ㄷ","ㄴ"],["ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㅁㅂㅅ","correct":true},{"t":"각 ㅁㅅㅂ","mis":"M3-1-u2-X05"},{"t":"각 ㅂㅁㅅ","mis":"M3-1-u2-X05"},{"t":"각 ㅂㅅㅁ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㅂ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㅁㅂㅅ 또는 각 ㅅㅂㅁ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅁ":[120.0,75.0],"ㅂ":[22.5,75],"ㅅ":[67.5,7.5]},"ray":[["ㅂ","ㅁ"],["ㅂ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 그림의 각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"각 ㅇㅈㅊ","correct":true},{"t":"각 ㅇㅊㅈ","mis":"M3-1-u2-X05"},{"t":"각 ㅈㅇㅊ","mis":"M3-1-u2-X05"},{"t":"각 ㅈㅊㅇ","mis":"M3-1-u2-X05"}],"explanation":["두 반직선이 만나는 점 ㅈ이 꼭짓점이에요.","꼭짓점을 가운데에 두어 각 ㅇㅈㅊ 또는 각 ㅊㅈㅇ이라고 읽어요.","꼭짓점이 가운데에 오지 않으면 다른 각을 가리켜요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅇ":[120.0,75.0],"ㅈ":[15,75],"ㅊ":[90.0,22.5]},"ray":[["ㅈ","ㅇ"],["ㅈ","ㅊ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUD