INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#4','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C4',1,'mc','auto','각이 직각인지 알아볼 때 대어 보는 도구는 무엇인가요?',ARRAY['M3-1-u2-X09']::text[],true,'{"seq":4,"concept":"M3-1-u2-C4","difficulty":1,"kind":"mc","stem":"각이 직각인지 알아볼 때 대어 보는 도구는 무엇인가요?","options":[{"t":"삼각자","correct":true},{"t":"지우개","mis":"M3-1-u2-X09"},{"t":"풀","mis":"M3-1-u2-X09"},{"t":"연필","mis":"M3-1-u2-X09"}],"explanation":["삼각자의 직각 부분을 대어 꼭 맞으면 직각이에요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"variant_rule":{"alt":[{"stem":"종이를 반듯하게 두 번 접었다가 펼쳤을 때 접힌 선이 만나 생기는 각을 무엇이라고 하나요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"꼭짓점","mis":"M3-1-u2-X06"},{"t":"곧은 선","mis":"M3-1-u2-X08"}],"explanation":["종이를 반듯하게 두 번 접으면 생기는 각이 직각이에요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"asset":null},{"stem":"직각을 나타낼 때 꼭짓점에 하는 표시는 무엇인가요?","options":[{"t":"ㄱ자 표시","correct":true},{"t":"동그라미 표시","mis":"M3-1-u2-X09"},{"t":"꼭짓점에 점 찍기","mis":"M3-1-u2-X06"},{"t":"변에 화살표","mis":"M3-1-u2-X02"}],"explanation":["직각은 꼭짓점에 작은 ㄱ자로 표시해요.","직각은 꼭짓점에 ㄱ자로 표시하고, 삼각자로 확인해요.","눈대중이 아니라 삼각자나 종이 접기로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#5','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C5',1,'mc','auto','직각삼각형에 있는 직각은 몇 개인가요?',ARRAY['M3-1-u2-X11','M3-1-u2-X09']::text[],true,'{"seq":5,"concept":"M3-1-u2-C5","difficulty":1,"kind":"mc","stem":"직각삼각형에 있는 직각은 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M3-1-u2-X11"},{"t":"3개","mis":"M3-1-u2-X11"},{"t":"0개","mis":"M3-1-u2-X09"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"variant_rule":{"alt":[{"stem":"직각삼각형은 어떤 삼각형인가요?","options":[{"t":"한 각이 직각인 삼각형","correct":true},{"t":"세 각이 모두 직각인 삼각형","mis":"M3-1-u2-X11"},{"t":"세 변의 길이가 모두 같은 삼각형","mis":"M3-1-u2-X11"},{"t":"직각이 하나도 없는 삼각형","mis":"M3-1-u2-X09"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"asset":null},{"stem":"한 각이 ◯◯인 삼각형을 직각삼각형이라고 해요. ◯◯에 알맞은 말은 무엇인가요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"꼭짓점","mis":"M3-1-u2-X06"},{"t":"곧은 선","mis":"M3-1-u2-X01"}],"explanation":["한 각이 직각인 삼각형을 직각삼각형이라고 해요.","직각삼각형의 직각은 1개 — 꼭짓점에 ㄱ자로 표시해요.","직각이 두 개면 두 변이 만나지 못해 삼각형이 될 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#6','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C6',1,'mc','auto','네 각이 모두 직각인 사각형의 이름은 무엇인가요?',ARRAY['M3-1-u2-X11','M3-1-u2-X12','M3-1-u2-X02']::text[],true,'{"seq":6,"concept":"M3-1-u2-C6","difficulty":1,"kind":"mc","stem":"네 각이 모두 직각인 사각형의 이름은 무엇인가요?","options":[{"t":"직사각형","correct":true},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"삼각형","mis":"M3-1-u2-X12"},{"t":"선분","mis":"M3-1-u2-X02"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"variant_rule":{"alt":[{"stem":"직사각형은 어떤 사각형인가요?","options":[{"t":"네 각이 모두 직각인 사각형","correct":true},{"t":"직각이 한 개 있는 사각형","mis":"M3-1-u2-X12"},{"t":"네 변의 길이가 모두 같은 사각형","mis":"M3-1-u2-X14"},{"t":"직각이 하나도 없는 사각형","mis":"M3-1-u2-X09"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"asset":null},{"stem":"직사각형은 네 각이 모두 ◯◯인 사각형이에요. ◯◯에 알맞은 말은 무엇인가요?","options":[{"t":"직각","correct":true},{"t":"반직선","mis":"M3-1-u2-X08"},{"t":"곧은 선","mis":"M3-1-u2-X01"},{"t":"꼭짓점","mis":"M3-1-u2-X06"}],"explanation":["네 각이 모두 직각인 사각형 = 직사각형.","직사각형 가운데 네 변의 길이까지 모두 같은 것 = 정사각형.","그래서 정사각형은 직사각형이라고도 할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
