INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#17','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C2',3,'error','auto','이 반직선을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u2-X03','M3-1-u2-X16']::text[],true,'{"seq":17,"concept":"M3-1-u2-C2","difficulty":3,"kind":"error","stem":"이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㅅㅇ은 반직선 ㅇㅅ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㅅㅇ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㅅ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅇ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㅅ에서 시작하니 반직선 ㅅㅇ이에요.","반직선 ㅇㅅ은 점 ㅇ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅅ":[45,54.0],"ㅇ":[97.5,36.0]},"ray":[["ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㄴㄷ은 반직선 ㄷㄴ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㄴㄷ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㄴ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㄷ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㄴ에서 시작하니 반직선 ㄴㄷ이에요.","반직선 ㄷㄴ은 점 ㄷ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄴ":[45,45],"ㄷ":[97.5,45]},"ray":[["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㄹㅁ은 반직선 ㅁㄹ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㄹㅁ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㄹ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅁ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㄹ에서 시작하니 반직선 ㄹㅁ이에요.","반직선 ㅁㄹ은 점 ㅁ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄹ":[45,60],"ㅁ":[97.5,30]},"ray":[["ㄹ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON 