INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#21','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C7',3,'mc','auto','가로 10 cm, 세로 7 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?',ARRAY['M3-1-u2-X14','M3-1-u2-X11','M3-1-u2-X15']::text[],true,'{"seq":21,"concept":"M3-1-u2-C7","difficulty":3,"kind":"mc","stem":"가로 10 cm, 세로 7 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 7 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 7 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 7 cm, 세로 7 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 7 cm예요.","남은 종이는 가로 10 − 7 = 3 cm, 세로 7 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[102.5,15]],[[102.5,15],[102.5,76.25]],[[102.5,76.25],[15,76.25]],[[15,76.25],[15,15]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 6 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 6 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 9 − 6 = 3 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[93.75,15]],[[93.75,15],[93.75,67.5]],[[93.75,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false}},{"stem":"가로 12 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 6 cm, 세로 6 cm인 정사각형","correct":true},{"t":"가로 12 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 12 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 12 − 6 = 6 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같아 — 정사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[120.0,15]],[[120.0,15],[120.0,67.5]],[[120.0,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#22','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C8',3,'ox','auto','사각형에 직각이 하나 있으면 직사각형이에요.',ARRAY['M3-1-u2-X12']::text[],true,'{"seq":22,"concept":"M3-1-u2-C8","difficulty":3,"kind":"ox","stem":"사각형에 직각이 하나 있으면 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"mis":"M3-1-u2-X12","explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[75,15],[105,75],[15,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"선분 4개로 둘러싸인 도형은 언제나 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[105,15],[90,75],[15,75]]]}],"tag":false}},{"stem":"꼭짓점이 4개인 도형은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[45,15],[75,15],[105,75],[15,75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#23','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C3',4,'mc','auto','점 ㅂ은 변 ㄹㄷ 위에 있어요. 각 ㅂㄹㅁ과 각 ㄷㄹㅁ은 어떤 사이인가요?',ARRAY['M3-1-u2-X07','M3-1-u2-X05','M3-1-u2-X08']::text[],true,'{"seq":23,"concept":"M3-1-u2-C3","difficulty":4,"kind":"mc","stem":"점 ㅂ은 변 ㄹㄷ 위에 있어요. 각 ㅂㄹㅁ과 각 ㄷㄹㅁ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㅂㄹㅁ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㅂㄹㅁ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㄹㅂ과 반직선 ㄹㄷ은 같은 반직선이에요(시작점 ㄹ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄹ":[67.5,75],"ㅂ":[97.5,75.0],"ㄷ":[127.5,75],"ㅁ":[15,15]},"ray":[["ㄹ","ㄷ"],["ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㄹ은 변 ㄴㄱ 위에 있어요. 각 ㄹㄴㄷ과 각 ㄱㄴㄷ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㄹㄴㄷ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㄹㄴㄷ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㄴㄹ과 반직선 ㄴㄱ은 같은 반직선이에요(시작점 ㄴ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄴ":[22.5,75],"ㄹ":[71.25,75.0],"ㄱ":[120,75],"ㄷ":[67.5,7.5]},"ray":[["ㄴ","ㄱ"],["ㄴ","ㄷ"]]}],"tag":false}},{"stem":"점 ㅇ은 변 ㅂㅁ 위에 있어요. 각 ㅇㅂㅅ과 각 ㅁㅂㅅ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㅇㅂㅅ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㅇㅂㅅ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㅂㅇ과 반직선 ㅂㅁ은 같은 반직선이에요(시작점 ㅂ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅂ":[15,75],"ㅇ":[67.5,75.0],"ㅁ":[120,75],"ㅅ":[90,22.5]},"ray":[["ㅂ","ㅁ"],["ㅂ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#24','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C7',4,'sa','auto','가로 7 cm, 세로 10 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u2-C7","difficulty":4,"kind":"sa","stem":"가로 7 cm, 세로 10 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 7 cm예요.","7 + 7 + 7 + 7 = 28 cm예요."],"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 5 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 5 cm예요.","5 + 5 + 5 + 5 = 20 cm예요."],"asset":null},{"stem":"가로 9 cm, 세로 4 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 4 cm예요.","4 + 4 + 4 + 4 = 16 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_b#25','math',3,1,'u2','','g3_1_math_u2_review_b','unit_review','M3-1-u2-C4',4,'essay','teacher','모눈이 없는 종이에 그린 각이 직각인지 알아보는 방법을 두 가지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u2-C4","difficulty":4,"kind":"essay","stem":"모눈이 없는 종이에 그린 각이 직각인지 알아보는 방법을 두 가지 써 보세요.","answer_guide":{"answer":"예: ① 삼각자의 직각 부분을 꼭짓점에 맞대어 두 변이 꼭 맞는지 본다. ② 종이를 반듯하게 두 번 접어 직각을 만들고 그 각에 대어 본다. 꼭 맞으면 직각이고 틈이 생기거나 넘치면 직각이 아니다.","scoring_points":["삼각자를 대어 보는 방법을 썼는가","종이를 두 번 접어 만든 직각을 대어 보는 방법을 썼는가","꼭 맞아야 직각이라고 썼는가"]},"explanation":["삼각자의 직각 부분을 대어 봐요.","종이를 반듯하게 두 번 접은 각을 대어 봐요.","꼭 맞으면 직각이에요(눈대중은 안 돼요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_c#1','math',3,1,'u2','','g3_1_math_u2_review_c','unit_review','M3-1-u2-C2',1,'mc','auto','이 곧은 선의 이름은 무엇인가요?',ARRAY['M3-1-u2-X02','M3-1-u2-X01']::text[],true,'{"seq":1,"concept":"M3-1-u2-C2","difficulty":1,"kind":"mc","stem":"이 곧은 선의 이름은 무엇인가요?","options":[{"t":"선분 ㄹㅁ","correct":true},{"t":"반직선 ㄹㅁ","mis":"M3-1-u2-X02"},{"t":"직선 ㄹㅁ","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㄹ과 점 ㅁ을 곧게 이은 선이라 두 끝이 있어요 — 선분이에요.","선분은 선분 ㄹㅁ, 선분 ㅁㄹ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄹ":[45,60],"ㅁ":[97.5,30]},"seg":[["ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 곧은 선의 이름은 무엇인가요?","options":[{"t":"선분 ㅂㅅ","correct":true},{"t":"반직선 ㅂㅅ","mis":"M3-1-u2-X02"},{"t":"직선 ㅂㅅ","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㅂ과 점 ㅅ을 곧게 이은 선이라 두 끝이 있어요 — 선분이에요.","선분은 선분 ㅂㅅ, 선분 ㅅㅂ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅂ":[45,30],"ㅅ":[97.5,60]},"seg":[["ㅂ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 곧은 선의 이름은 무엇인가요?","options":[{"t":"선분 ㅇㅈ","correct":true},{"t":"반직선 ㅇㅈ","mis":"M3-1-u2-X02"},{"t":"직선 ㅇㅈ","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 어디에 있는지 살펴봐요.","점 ㅇ과 점 ㅈ을 곧게 이은 선이라 두 끝이 있어요 — 선분이에요.","선분은 선분 ㅇㅈ, 선분 ㅈㅇ 어느 쪽으로 읽어도 돼요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅇ":[45,54.0],"ㅈ":[97.5,36.0]},"seg":[["ㅇ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_c#2','math',3,1,'u2','','g3_1_math_u2_review_c','unit_review','M3-1-u2-C2',1,'mc','auto','두 점을 곧게 이은 선을 무엇이라고 하나요?',ARRAY['M3-1-u2-X02','M3-1-u2-X01']::text[],true,'{"seq":2,"concept":"M3-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 점을 곧게 이은 선을 무엇이라고 하나요?","options":[{"t":"선분","correct":true},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["두 끝이 있는 곧은 선이 선분이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"variant_rule":{"alt":[{"stem":"한 점에서 시작하여 한쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"반직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["시작하는 끝 하나만 있는 곧은 선이 반직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null},{"stem":"두 점을 지나 양쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"직선","correct":true},{"t":"선분","mis":"M3-1-u2-X02"},{"t":"반직선","mis":"M3-1-u2-X02"},{"t":"굽은 선","mis":"M3-1-u2-X01"}],"explanation":["끝이 없는 곧은 선이 직선이에요.","선분은 끝이 2개, 반직선은 1개, 직선은 0개예요.","셋 다 곧은 선이에요 — 끝의 수로 구별해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
