INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_c#8','math',3,1,'u2','','g3_1_math_u2_review_c','unit_review','M3-1-u2-C8',1,'mc','auto','로켓 그림에서 날개는 무슨 도형인가요?',ARRAY['M3-1-u2-X14','M3-1-u2-X09']::text[],true,'{"seq":8,"concept":"M3-1-u2-C8","difficulty":1,"kind":"mc","stem":"로켓 그림에서 날개는 무슨 도형인가요?","options":[{"t":"직각삼각형","correct":true},{"t":"정사각형","mis":"M3-1-u2-X14"},{"t":"직사각형","mis":"M3-1-u2-X14"},{"t":"삼각형","mis":"M3-1-u2-X09"}],"explanation":["날개 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","한 각이 직각인 삼각형 — 직각삼각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":135,"h":142.5,"grid":15,"poly":[[[52.5,37.5],[82.5,37.5],[82.5,105],[52.5,105]],[[52.5,37.5],[82.5,37.5],[67.5,22.5]],[[52.5,82.5],[52.5,105],[30,105]],[[82.5,82.5],[82.5,105],[105,105]],[[60,52.5],[75,52.5],[75,67.5],[60,67.5]]],"seg":[[[60,105],[60,124.50000000000001]],[[67.5,105],[67.5,129.0]],[[75,105],[75,124.50000000000001]]],"cap":"로켓"}],"tag":false},"variant_rule":{"alt":[{"stem":"로켓 그림에서 창은 무슨 도형인가요?","options":[{"t":"정사각형","correct":true},{"t":"직사각형만","mis":"M3-1-u2-X13"},{"t":"직각삼각형","mis":"M3-1-u2-X09"},{"t":"원","mis":"M3-1-u2-X01"}],"explanation":["창 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","네 각이 모두 직각이고 네 변의 길이가 모두 같아요 — 정사각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":135,"h":142.5,"grid":15,"poly":[[[52.5,37.5],[82.5,37.5],[82.5,105],[52.5,105]],[[52.5,37.5],[82.5,37.5],[67.5,22.5]],[[52.5,82.5],[52.5,105],[30,105]],[[82.5,82.5],[82.5,105],[105,105]],[[60,52.5],[75,52.5],[75,67.5],[60,67.5]]],"seg":[[[60,105],[60,124.50000000000001]],[[67.5,105],[67.5,129.0]],[[75,105],[75,124.50000000000001]]],"cap":"로켓"}],"tag":false}},{"stem":"로켓 그림에서 몸체는 무슨 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X09"},{"t":"삼각형","mis":"M3-1-u2-X09"}],"explanation":["몸체 부분의 꼭짓점과 변을 모눈으로 살펴봐요.","네 각이 모두 직각이지만 네 변의 길이가 모두 같지는 않아요 — 직사각형이에요.","도형의 이름은 성질로 정확히 불러요(그냥 「세모·네모」가 아니라)."],"asset":{"type":"geo","items":[{"w":135,"h":142.5,"grid":15,"poly":[[[52.5,37.5],[82.5,37.5],[82.5,105],[52.5,105]],[[52.5,37.5],[82.5,37.5],[67.5,22.5]],[[52.5,82.5],[52.5,105],[30,105]],[[82.5,82.5],[82.5,105],[105,105]],[[60,52.5],[75,52.5],[75,67.5],[60,67.5]]],"seg":[[[60,105],[60,124.50000000000001]],[[67.5,105],[67.5,129.0]],[[75,105],[75,124.50000000000001]]],"cap":"로켓"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
