INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_c#21','math',3,1,'u2','','g3_1_math_u2_review_c','unit_review','M3-1-u2-C7',3,'ox','auto','네 변의 길이가 모두 같은 사각형은 모두 정사각형이에요.',ARRAY['M3-1-u2-X12']::text[],true,'{"seq":21,"concept":"M3-1-u2-C7","difficulty":3,"kind":"ox","stem":"네 변의 길이가 모두 같은 사각형은 모두 정사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"mis":"M3-1-u2-X12","explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이 사각형은 네 변의 길이가 모두 같으니 정사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false}},{"stem":"네 변의 길이가 같기만 하면 정사각형이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 정사각형이라서","correct":true},{"t":"네 변의 길이가 같으면 정사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["정사각형의 조건은 두 가지 — 네 각이 모두 직각, 네 변의 길이가 모두 같음.","이 사각형은 네 변의 길이는 같지만 각이 직각이 아니에요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,45],[60,75],[15,45]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
