INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#13','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C4',2,'mc','auto','긴바늘이 12를 가리킬 때 두 바늘이 이루는 각이 직각인 시각은 어느 것인가요?',ARRAY['M3-1-u2-X09','M3-1-u2-X08']::text[],true,'{"seq":13,"concept":"M3-1-u2-C4","difficulty":2,"kind":"mc","stem":"긴바늘이 12를 가리킬 때 두 바늘이 이루는 각이 직각인 시각은 어느 것인가요?","options":[{"t":"9시","correct":true},{"t":"8시","mis":"M3-1-u2-X09"},{"t":"10시","mis":"M3-1-u2-X09"},{"t":"12시","mis":"M3-1-u2-X08"}],"explanation":["긴바늘이 12, 짧은바늘이 9을 가리키면 두 바늘이 반듯하게 꺾여요.","시계의 두 바늘에 삼각자의 직각을 대면 꼭 맞아요.","9시일 때 직각이에요(6시는 곧은 선이 돼요)."],"asset":{"type":"clock2","h":9,"m":0},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 긴바늘이 12를 가리킬 때 두 바늘이 이루는 각이 직각인 시각은 어느 것인가요?","options":[{"t":"3시","correct":true},{"t":"1시","mis":"M3-1-u2-X09"},{"t":"5시","mis":"M3-1-u2-X09"},{"t":"6시","mis":"M3-1-u2-X08"}],"explanation":["긴바늘이 12, 짧은바늘이 3을 가리키면 두 바늘이 반듯하게 꺾여요.","시계의 두 바늘에 삼각자의 직각을 대면 꼭 맞아요.","3시일 때 직각이에요(6시는 곧은 선이 돼요)."],"asset":{"type":"clock2","h":3,"m":0}},{"stem":"이번에는 다른 그림이에요. 긴바늘이 12를 가리킬 때 두 바늘이 이루는 각이 직각인 시각은 어느 것인가요?","options":[{"t":"3시","correct":true},{"t":"2시","mis":"M3-1-u2-X09"},{"t":"4시","mis":"M3-1-u2-X09"},{"t":"6시","mis":"M3-1-u2-X08"}],"explanation":["긴바늘이 12, 짧은바늘이 3을 가리키면 두 바늘이 반듯하게 꺾여요.","시계의 두 바늘에 삼각자의 직각을 대면 꼭 맞아요.","3시일 때 직각이에요(6시는 곧은 선이 돼요)."],"asset":{"type":"clock2","h":3,"m":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
