INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#15','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C7',2,'mc','auto','직사각형과 정사각형의 같은 점은 무엇인가요?',ARRAY['M3-1-u2-X14','M3-1-u2-X11','M3-1-u2-X15']::text[],true,'{"seq":15,"concept":"M3-1-u2-C7","difficulty":2,"kind":"mc","stem":"직사각형과 정사각형의 같은 점은 무엇인가요?","options":[{"t":"네 각이 모두 직각이에요","correct":true},{"t":"네 변의 길이가 모두 같아요","mis":"M3-1-u2-X14"},{"t":"직각이 1개씩 있어요","mis":"M3-1-u2-X11"},{"t":"변이 3개씩 있어요","mis":"M3-1-u2-X15"}],"explanation":["둘 다 네 각이 모두 직각인 사각형이에요.","정사각형은 네 변의 길이까지 모두 같아요.","다른 점은 변의 길이예요."],"variant_rule":{"alt":[{"stem":"직사각형이 정사각형이 되려면 무엇이 더 필요한가요?","options":[{"t":"네 변의 길이가 모두 같아야 해요","correct":true},{"t":"직각이 하나 더 있어야 해요","mis":"M3-1-u2-X12"},{"t":"꼭짓점이 하나 더 있어야 해요","mis":"M3-1-u2-X15"},{"t":"기울어져 있어야 해요","mis":"M3-1-u2-X10"}],"explanation":["둘 다 네 각이 모두 직각인 사각형이에요.","정사각형은 네 변의 길이까지 모두 같아요.","다른 점은 변의 길이예요."],"asset":null},{"stem":"직사각형과 정사각형의 다른 점은 무엇인가요?","options":[{"t":"네 변의 길이가 모두 같은지","correct":true},{"t":"네 각이 모두 직각인지","mis":"M3-1-u2-X12"},{"t":"꼭짓점의 수","mis":"M3-1-u2-X15"},{"t":"변의 수","mis":"M3-1-u2-X15"}],"explanation":["둘 다 네 각이 모두 직각인 사각형이에요.","정사각형은 네 변의 길이까지 모두 같아요.","다른 점은 변의 길이예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
