INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#17','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C2',3,'error','auto','이 반직선을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u2-X03','M3-1-u2-X16']::text[],true,'{"seq":17,"concept":"M3-1-u2-C2","difficulty":3,"kind":"error","stem":"이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㄹㅁ은 반직선 ㅁㄹ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㄹㅁ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㄹ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅁ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㄹ에서 시작하니 반직선 ㄹㅁ이에요.","반직선 ㅁㄹ은 점 ㅁ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㄹ":[45,60],"ㅁ":[97.5,30]},"ray":[["ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㅂㅅ은 반직선 ㅅㅂ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㅂㅅ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㅂ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅅ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㅂ에서 시작하니 반직선 ㅂㅅ이에요.","반직선 ㅅㅂ은 점 ㅅ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅂ":[45,30],"ㅅ":[97.5,60]},"ray":[["ㅂ","ㅅ"]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 반직선을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「반직선 ㅇㅈ은 반직선 ㅈㅇ이라고도 해.」","correct":true,"mis_target":"M3-1-u2-X03"},{"t":"서윤 — 「이건 반직선 ㅇㅈ이야.」","mis":"M3-1-u2-X16"},{"t":"은우 — 「시작점은 점 ㅇ이야.」","mis":"M3-1-u2-X16"},{"t":"하랑 — 「점 ㅈ 쪽으로 끝없이 늘어나.」","mis":"M3-1-u2-X16"}],"explanation":["반직선은 시작하는 점을 먼저 읽어요.","이 반직선은 점 ㅇ에서 시작하니 반직선 ㅇㅈ이에요.","반직선 ㅈㅇ은 점 ㅈ에서 시작하는 다른 반직선이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":90,"pts":{"ㅇ":[45,54.0],"ㅈ":[97.5,36.0]},"ray":[["ㅇ","ㅈ"]]}],"tag":false}}]}}'::jsonb) ON 