INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#18','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C4',3,'sa','auto','두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M3-1-u2-C4","difficulty":3,"kind":"sa","stem":"두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","곧은 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,67.5],[120,67.5]],[[67.5,67.5],[67.5,7.5]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","기울어진 선 위의 한 점에서 반듯하게 세운 선의 양쪽에 직각이 2개 생겨요.","직각은 모두 2개예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[90,52.5]],[[52.5,33.75],[37.5,63.75]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 두 곧은 선이 반듯하게 만났어요. 그림에서 찾을 수 있는 직각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["두 선이 만나는 점 둘레를 한 바퀴 돌며 삼각자를 대어 봐요.","두 직선이 직각으로 만나는 점 둘레에 직각이 4개 생겨요.","직각은 모두 4개예요."],"asset":{"type":"geo","items":[{"w":135,"h":97.5,"seg":[[[15,45],[120,45]],[[67.5,7.5],[67.5,82.5]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
