INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#21','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C7',3,'mc','auto','가로 12 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?',ARRAY['M3-1-u2-X15','M3-1-u2-X11']::text[],true,'{"seq":21,"concept":"M3-1-u2-C7","difficulty":3,"kind":"mc","stem":"가로 12 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 6 cm, 세로 6 cm인 정사각형","correct":true},{"t":"가로 12 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 12 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 12 − 6 = 6 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같아 — 정사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[120.0,15]],[[120.0,15],[120.0,67.5]],[[120.0,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 7 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 7 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 7 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 7 cm, 세로 7 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 7 cm예요.","남은 종이는 가로 10 − 7 = 3 cm, 세로 7 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[102.5,15]],[[102.5,15],[102.5,76.25]],[[102.5,76.25],[15,76.25]],[[15,76.25],[15,15]]]}],"tag":false}},{"stem":"가로 9 cm, 세로 6 cm인 직사각형 모양 종이에서 가장 큰 정사각형을 잘라 냈어요. 남은 종이는 어떤 도형인가요?","options":[{"t":"가로 3 cm, 세로 6 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 6 cm인 정사각형","mis":"M3-1-u2-X14"},{"t":"직각삼각형","mis":"M3-1-u2-X11"},{"t":"가로 6 cm, 세로 6 cm인 직사각형","mis":"M3-1-u2-X15"}],"explanation":["가장 큰 정사각형의 한 변은 짧은 변과 같은 6 cm예요.","남은 종이는 가로 9 − 6 = 3 cm, 세로 6 cm예요.","네 각이 모두 직각이고 네 변이 모두 같지는 않아 — 직사각형이에요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"seg":[[[15,15],[93.75,15]],[[93.75,15],[93.75,67.5]],[[93.75,67.5],[15,67.5]],[[15,67.5],[15,15]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#22','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C8',3,'ox','auto','꼭짓점이 4개인 도형은 모두 직사각형이에요.',ARRAY['M3-1-u2-X12']::text[],true,'{"seq":22,"concept":"M3-1-u2-C8","difficulty":3,"kind":"ox","stem":"꼭짓점이 4개인 도형은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"mis":"M3-1-u2-X12","explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[45,15],[75,15],[105,75],[15,75]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형에 직각이 하나 있으면 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[75,15],[105,75],[15,60]]]}],"tag":false}},{"stem":"선분 4개로 둘러싸인 도형은 언제나 직사각형이에요.","answer":"X","reason_options":[{"t":"네 각이 모두 직각이어야 직사각형이라서","correct":true},{"t":"곧은 선 4개로 둘러싸이면 직사각형이라서","mis":"M3-1-u2-X12"}],"explanation":["선분 4개로 둘러싸인 도형은 사각형이에요.","직사각형은 사각형 가운데 네 각이 모두 직각인 것만이에요.","직각이 없거나 몇 개뿐인 사각형도 많아요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[30,15],[105,15],[90,75],[15,75]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#23','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C3',4,'mc','auto','점 ㅇ은 변 ㅂㅁ 위에 있어요. 각 ㅇㅂㅅ과 각 ㅁㅂㅅ은 어떤 사이인가요?',ARRAY['M3-1-u2-X07','M3-1-u2-X05','M3-1-u2-X08']::text[],true,'{"seq":23,"concept":"M3-1-u2-C3","difficulty":4,"kind":"mc","stem":"점 ㅇ은 변 ㅂㅁ 위에 있어요. 각 ㅇㅂㅅ과 각 ㅁㅂㅅ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㅇㅂㅅ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㅇㅂㅅ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㅂㅇ과 반직선 ㅂㅁ은 같은 반직선이에요(시작점 ㅂ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㅂ":[15,75],"ㅇ":[67.5,75.0],"ㅁ":[120,75],"ㅅ":[90,22.5]},"ray":[["ㅂ","ㅁ"],["ㅂ","ㅅ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"점 ㅂ은 변 ㄹㄷ 위에 있어요. 각 ㅂㄹㅁ과 각 ㄷㄹㅁ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㅂㄹㅁ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㅂㄹㅁ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㄹㅂ과 반직선 ㄹㄷ은 같은 반직선이에요(시작점 ㄹ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄹ":[67.5,75],"ㅂ":[97.5,75.0],"ㄷ":[127.5,75],"ㅁ":[15,15]},"ray":[["ㄹ","ㄷ"],["ㄹ","ㅁ"]]}],"tag":false}},{"stem":"점 ㄹ은 변 ㄴㄱ 위에 있어요. 각 ㄹㄴㄷ과 각 ㄱㄴㄷ은 어떤 사이인가요?","options":[{"t":"같은 각이에요 — 두 변이 같은 반직선이라서","correct":true},{"t":"각 ㄹㄴㄷ이 더 작아요 — 변이 짧아서","mis":"M3-1-u2-X07"},{"t":"다른 각이에요 — 이름이 달라서","mis":"M3-1-u2-X05"},{"t":"각 ㄹㄴㄷ은 각이 아니에요","mis":"M3-1-u2-X08"}],"explanation":["반직선 ㄴㄹ과 반직선 ㄴㄱ은 같은 반직선이에요(시작점 ㄴ, 같은 쪽).","그래서 두 각은 꼭짓점도 두 변도 같아요.","변 위의 어느 점으로 읽어도 같은 각이에요."],"asset":{"type":"geo","items":[{"w":142.5,"h":97.5,"pts":{"ㄴ":[22.5,75],"ㄹ":[71.25,75.0],"ㄱ":[120,75],"ㄷ