INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#24','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C7',4,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u2-C7","difficulty":4,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 4 cm예요.","4 + 4 + 4 + 4 = 16 cm예요."],"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 10 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 7 cm예요.","7 + 7 + 7 + 7 = 28 cm예요."],"asset":null},{"stem":"가로 8 cm, 세로 5 cm인 직사각형 안에 그릴 수 있는 가장 큰 정사각형의 네 변의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["정사각형의 한 변은 직사각형의 짧은 변보다 길 수 없어요.","가장 큰 정사각형의 한 변은 5 cm예요.","5 + 5 + 5 + 5 = 20 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u2_review_d#25','math',3,1,'u2','','g3_1_math_u2_review_d','unit_review','M3-1-u2-C5',4,'essay','teacher','시우는 「이 삼각형은 직각이 위쪽에 있으니까 직각삼각형이 아니야.」라고 말했어요. 시우의 말이 잘못된 까닭과 직각삼각형인지 알아보는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u2-C5","difficulty":4,"kind":"essay","stem":"시우는 「이 삼각형은 직각이 위쪽에 있으니까 직각삼각형이 아니야.」라고 말했어요. 시우의 말이 잘못된 까닭과 직각삼각형인지 알아보는 방법을 써 보세요.","answer_guide":{"answer":"예: 직각삼각형은 한 각이 직각인 삼각형이고, 직각이 어느 쪽에 있든 상관없다. 세 꼭짓점에 삼각자의 직각 부분을 대어 보아 한 각이 꼭 맞으면 직각삼각형이다.","scoring_points":["직각의 방향은 상관없다고 썼는가","한 각이 직각이면 직각삼각형이라고 썼는가","삼각자를 대어 보는 방법을 썼는가"]},"explanation":["직각삼각형 = 한 각이 직각인 삼각형.","직각이 위·옆·기울어진 곳에 있어도 돼요.","꼭짓점마다 삼각자를 대어 확인해요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[60,15],[105,60],[15,60]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
